/* Verified synthetic narration and measured sentence timing. */
window.MACGYVER_PACKAGING_NARRATION={"version":"33.0.3","tours":{"interposer":{"zh-TW":{"file":"assets/packaging-tour-v33/audio/interposer.zh-TW.m4a","sha256":"87d6cc9f34170a888f4927ad94797c83b88a0d4c7f1651d3a329c40af4a2b4c6","cues":[{"start":0.35,"end":11.857854,"text":"先從上方看：中央是運算晶片，周圍是 HBM 記憶體堆疊，下方共同的平台是矽中介層。","chapterIndex":0,"sentenceIndex":0},{"start":12.037854,"end":25.053875,"text":"這個教學場景把微小封裝放大成一座城市；先找出「誰負責計算、誰存資料、誰把兩者連起來」，再靠近細節。","chapterIndex":0,"sentenceIndex":1},{"start":30.35,"end":35.494188,"text":"鏡頭降低，分清晶粒、中介層與封裝基板。","chapterIndex":1,"sentenceIndex":0},{"start":35.674188,"end":43.263813,"text":"中介層承接高密度晶粒間連線；基板把訊號與電源帶往電路板。","chapterIndex":1,"sentenceIndex":1},{"start":43.443812,"end":54.169854,"text":"這裡講的是矽中介層型 2.5D 結構，不能把所有 CoWoS 變體都畫成同一片矽板。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":67.407562,"text":"沿著晶片邊緣飛行，注意並行連線如何跨向 HBM。","chapterIndex":2,"sentenceIndex":0},{"start":67.587563,"end":73.666396,"text":"高頻寬不只靠單條線變快，也靠許多通道合作。","chapterIndex":2,"sentenceIndex":1},{"start":73.846396,"end":85.057979,"text":"發光線代表連接關係，不是電子的真實速度；實際設計還要計算寄生效應、串擾與時序裕量。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":95.423667,"text":"把整體拆成待組裝的晶粒、中介層與基板。","chapterIndex":3,"sentenceIndex":0},{"start":95.603667,"end":106.701083,"text":"先檢查各元件，再規劃貼合、填膠與接合後測試，能避免到最後才發現昂貴的缺陷。","chapterIndex":3,"sentenceIndex":1},{"start":106.881083,"end":114.879688,"text":"這是概念流程；實際先後順序與材料條件必須依製程規範決定。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":127.355583,"text":"展開分層結構，辨認晶粒接點、中介層佈線與穿矽孔。","chapterIndex":4,"sentenceIndex":0},{"start":127.535583,"end":137.126896,"text":"不要把 HBM 內部堆疊的垂直連線，和中介層通往下方基板的連線混為一談。","chapterIndex":4,"sentenceIndex":1},{"start":137.306896,"end":145.314792,"text":"現在用眼睛追一遍：資料往鄰居走，供電與外部連接往基板走。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":155.447792,"text":"資料從記憶體到運算核心，再回到記憶體。","chapterIndex":5,"sentenceIndex":0},{"start":155.627792,"end":163.852375,"text":"問三件事：每秒搬多少資料、每位元耗多少能量、最壞情況延遲多大。","chapterIndex":5,"sentenceIndex":1},{"start":164.032375,"end":174.922542,"text":"靠近可以縮短互連，但不能直接推論整個系統一定更省電；工作負載與控制器也會改變結果。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":187.574417,"text":"熱點從運算晶粒浮現，向上穿過介面材料與散熱結構。","chapterIndex":6,"sentenceIndex":0},{"start":187.754417,"end":193.941375,"text":"旁邊的記憶體也有溫度限制，不能只盯著中央晶片。","chapterIndex":6,"sentenceIndex":1},{"start":194.121375,"end":205.17675,"text":"紅色是概念熱區，不是量測溫度；真正比較散熱方案，要固定功率、環境與接觸條件。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":217.589104,"text":"鏡頭停在檢查站：外觀、接點影像與電性測試回答不同問題。","chapterIndex":7,"sentenceIndex":0},{"start":217.769104,"end":226.174792,"text":"漂亮的 X 光影像不等於每條訊號都正常；電性通過也不代表長期可靠。","chapterIndex":7,"sentenceIndex":1},{"start":226.354792,"end":234.291438,"text":"把缺陷位置、測試結果與製程批次連起來，才能找到真正的改善方向。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":248.289917,"text":"拉高鏡頭，比較多放記憶體、縮短走線與維持可製造性的拉扯。","chapterIndex":8,"sentenceIndex":0},{"start":248.469917,"end":255.273333,"text":"封裝面積、翹曲、供電與散熱都會牽動成本和良率。","chapterIndex":8,"sentenceIndex":1},{"start":255.453333,"end":262.37825,"text":"中介層的價值在於整合適合的系統，而不是把所有空間塞滿。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":284.240167,"text":"最後俯瞰整條技術路線：定義需求、配置運算與 HBM、設計互連和供電、安排組裝、驗證熱與可靠度。","chapterIndex":9,"sentenceIndex":0},{"start":284.420167,"end":295.305167,"text":"若你能指出資料從哪裡來、熱往哪裡走、哪個接點最需要證據，就已看懂這個封裝的核心。","chapterIndex":9,"sentenceIndex":1}]},"en":{"file":"assets/packaging-tour-v33/audio/interposer.en.m4a","sha256":"a5631d3478aaa4dc43ae0445bfe0e278c40bc58ff36883db3dd395a5f41a0767","cues":[{"start":0.35,"end":9.012771,"text":"Start overhead: a compute die sits beside HBM memory stacks, all supported by a silicon interposer.","chapterIndex":0,"sentenceIndex":0},{"start":9.192771,"end":13.281271,"text":"This teaching scene enlarges a tiny package into a city.","chapterIndex":0,"sentenceIndex":1},{"start":13.461271,"end":21.224083,"text":"First identify who computes, who stores data and who connects them; then descend into the details.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":35.8175,"text":"Lower the camera and separate the dies, interposer and package substrate.","chapterIndex":1,"sentenceIndex":0},{"start":35.9975,"end":43.407708,"text":"The interposer handles dense die-to-die routing; the substrate connects the assembly to the circuit board.","chapterIndex":1,"sentenceIndex":1},{"start":43.587708,"end":54.3675,"text":"This tour represents silicon-interposer 2.5D packaging, not every CoWoS variant, which can use different interconnect structures.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":65.583667,"text":"Fly along the die edges and follow parallel connections toward HBM.","chapterIndex":2,"sentenceIndex":0},{"start":65.763667,"end":72.37525,"text":"Bandwidth comes from many channels working together, not simply from accelerating one wire.","chapterIndex":2,"sentenceIndex":1},{"start":72.55525,"end":76.509,"text":"Glowing routes show connectivity rather than electron speed.","chapterIndex":2,"sentenceIndex":2},{"start":76.689,"end":82.5955,"text":"Real design also evaluates parasitics, crosstalk and timing margin.","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":94.703833,"text":"Separate the dies, interposer and substrate before assembly.","chapterIndex":3,"sentenceIndex":0},{"start":94.883833,"end":104.319542,"text":"Inspect components, then plan placement, underfill and post-bond tests so defects are not discovered only after costly integration.","chapterIndex":3,"sentenceIndex":1},{"start":104.499542,"end":114.155875,"text":"This is a conceptual workflow: actual sequencing, materials and process conditions depend on the qualified manufacturing flow.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":127.409562,"text":"In the separated layers, identify die contacts, interposer wiring and through-silicon vias.","chapterIndex":4,"sentenceIndex":0},{"start":127.589562,"end":135.856104,"text":"Vertical connections inside an HBM stack are not the same structures as connections through the interposer toward the substrate.","chapterIndex":4,"sentenceIndex":1},{"start":136.036104,"end":144.081917,"text":"Trace the distinct routes: data travels to neighboring dies, while power and external connections reach the substrate.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":153.484208,"text":"Follow data from memory to compute and back.","chapterIndex":5,"sentenceIndex":0},{"start":153.664208,"end":161.531375,"text":"Ask three questions: how much data per second, how much energy per bit and what worst-case latency?","chapterIndex":5,"sentenceIndex":1},{"start":161.711375,"end":167.806312,"text":"Shorter links can help, but proximity alone does not guarantee lower system power.","chapterIndex":5,"sentenceIndex":2},{"start":167.986312,"end":172.67825,"text":"Workload, controllers and utilization also shape the result.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":185.791958,"text":"Heat leaves the compute die through interface material and cooling structures above it.","chapterIndex":6,"sentenceIndex":0},{"start":185.971958,"end":189.26525,"text":"Nearby memory also has temperature limits.","chapterIndex":6,"sentenceIndex":1},{"start":189.44525,"end":194.467521,"text":"The red region is an illustrative hotspot, not measured temperature.","chapterIndex":6,"sentenceIndex":2},{"start":194.647521,"end":201.462688,"text":"A fair cooling comparison holds power, ambient conditions and contact conditions constant.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":217.54625,"text":"At inspection, visual checks, joint imaging and electrical tests answer different questions.","chapterIndex":7,"sentenceIndex":0},{"start":217.72625,"end":226.062771,"text":"A clean X-ray image does not prove every signal works; an electrical pass does not prove lifetime reliability.","chapterIndex":7,"sentenceIndex":1},{"start":226.242771,"end":234.133979,"text":"Connect defect locations, test results and process lots to identify meaningful corrective actions.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":246.361396,"text":"Rise above the package and compare more memory, shorter routes and manufacturability.","chapterIndex":8,"sentenceIndex":0},{"start":246.541396,"end":252.919854,"text":"Package area, warpage, power delivery and cooling interact with cost and yield.","chapterIndex":8,"sentenceIndex":1},{"start":253.099854,"end":262.236875,"text":"The interposer is valuable because it enables a balanced system, not because every available location is filled with silicon.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":284.223292,"text":"Finish with the complete route: define requirements, place compute and HBM, design interconnect and power, plan assembly, then verify thermal behavior and reliability.","chapterIndex":9,"sentenceIndex":0},{"start":284.403292,"end":293.167708,"text":"If you can show where data begins, where heat leaves and which connection needs evidence, you understand the core of this package.","chapterIndex":9,"sentenceIndex":1}]},"zh-CN":{"file":"assets/packaging-tour-v33/audio/interposer.zh-CN.m4a","sha256":"9d29d10be3481ddd151be106071dcce7d53b2b105b4bbc0e62e228fa2f46f26d","cues":[{"start":0.35,"end":12.697229,"text":"先从上方看：中央是计算芯片，周围是 HBM 内存堆叠，下方共同的平台是硅中介层。","chapterIndex":0,"sentenceIndex":0},{"start":12.877229,"end":26.5385,"text":"这个教学场景把微小封装放大成一座城市；先找出谁负责计算、谁存数据、谁把两者连起来，再靠近细节。","chapterIndex":0,"sentenceIndex":1},{"start":30.35,"end":35.645167,"text":"镜头降低，分清晶粒、中介层与封装基板。","chapterIndex":1,"sentenceIndex":0},{"start":35.825167,"end":43.353708,"text":"中介层承接高密度晶粒间连线；基板把信号与电源带往电路板。","chapterIndex":1,"sentenceIndex":1},{"start":43.533708,"end":53.516125,"text":"这里讲的是硅中介层型 2.5D 结构，不能把所有 CoWoS 变体都画成同一片硅板。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":67.892375,"text":"沿着芯片边缘飞行，注意并行连线如何跨向 HBM。","chapterIndex":2,"sentenceIndex":0},{"start":68.072375,"end":73.913167,"text":"高带宽不只靠单条线变快，也靠许多通道合作。","chapterIndex":2,"sentenceIndex":1},{"start":74.093167,"end":85.231313,"text":"发光线代表连接关系，不是电子的真实速度；实际设计还要计算寄生效应、串扰与时序裕量。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":95.2755,"text":"把整体拆成待组装的晶粒、中介层与基板。","chapterIndex":3,"sentenceIndex":0},{"start":95.4555,"end":106.162542,"text":"先检查各元件，再规划贴合、填胶与接合后测试，能避免到最后才发现昂贵的缺陷。","chapterIndex":3,"sentenceIndex":1},{"start":106.342542,"end":113.925417,"text":"这是概念流程；实际先后顺序与材料条件必须依工艺规范决定。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":127.130104,"text":"展开分层结构，辨认晶粒接点、中介层布线与穿硅孔。","chapterIndex":4,"sentenceIndex":0},{"start":127.310104,"end":137.371292,"text":"不要把 HBM 内部堆叠的垂直连线，和中介层通往下方基板的连线混为一谈。","chapterIndex":4,"sentenceIndex":1},{"start":137.551292,"end":145.220646,"text":"现在用眼睛追一遍：数据往邻居走，供电与外部连接往基板走。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":155.281896,"text":"数据从内存到计算核心，再回到内存。","chapterIndex":5,"sentenceIndex":0},{"start":155.461896,"end":164.189354,"text":"问三件事：每秒搬多少数据、每比特耗多少能量、最坏情况延迟多大。","chapterIndex":5,"sentenceIndex":1},{"start":164.369354,"end":175.348688,"text":"靠近可以缩短互连，但不能直接推论整个系统一定更省电；工作负载与控制器也会改变结果。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":187.081938,"text":"热点从计算晶粒浮现，向上穿过界面材料与散热结构。","chapterIndex":6,"sentenceIndex":0},{"start":187.261937,"end":192.873146,"text":"旁边的内存也有温度限制，不能只盯着中央芯片。","chapterIndex":6,"sentenceIndex":1},{"start":193.053146,"end":203.595604,"text":"红色是概念热区，不是测量温度；真正比较散热方案，要固定功率、环境与接触条件。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":218.249021,"text":"镜头停在检查站：外观、接点影像与电性测试回答不同问题。","chapterIndex":7,"sentenceIndex":0},{"start":218.429021,"end":227.663271,"text":"漂亮的 X 光影像不等于每条信号都正常；电性通过也不代表长期可靠。","chapterIndex":7,"sentenceIndex":1},{"start":227.843271,"end":236.25625,"text":"把缺陷位置、测试结果与工艺批次连起来，才能找到真正的改善方向。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":248.497,"text":"拉高镜头，比较多放内存、缩短走线与维持可制造性的拉扯。","chapterIndex":8,"sentenceIndex":0},{"start":248.677,"end":255.724083,"text":"封装面积、翘曲、供电与散热都会牵动成本和良率。","chapterIndex":8,"sentenceIndex":1},{"start":255.904083,"end":263.348354,"text":"中介层的价值在于整合适合的系统，而不是把所有空间塞满。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":284.560625,"text":"最后俯瞰整条技术路线：定义需求、配置计算与 HBM、设计互连和供电、安排组装、验证热与可靠性。","chapterIndex":9,"sentenceIndex":0},{"start":284.740625,"end":295.0425,"text":"若你能指出数据从哪里来、热往哪里走、哪个接点最需要证据，就已看懂这个封装的核心。","chapterIndex":9,"sentenceIndex":1}]},"ja":{"file":"assets/packaging-tour-v33/audio/interposer.ja.m4a","sha256":"886951272dc4ced79630126ec3d8fe0537dcd59419e0d3daf2797eee89f5b8f7","cues":[{"start":0.35,"end":10.738542,"text":"上空から、演算ダイ、周囲の HBM メモリースタック、その下のシリコンインターポーザーを見ます。","chapterIndex":0,"sentenceIndex":0},{"start":10.918542,"end":15.7035,"text":"小さなパッケージを街に見立てた教材です。","chapterIndex":0,"sentenceIndex":1},{"start":15.8835,"end":23.845063,"text":"まず計算、記憶、接続の役割を見分けてから、細部へ近づきましょう。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":35.288021,"text":"ダイ、インターポーザー、パッケージ基板を分けて見ます。","chapterIndex":1,"sentenceIndex":0},{"start":35.468021,"end":43.876729,"text":"インターポーザーは高密度のダイ間配線、基板は回路基板への接続を担います。","chapterIndex":1,"sentenceIndex":1},{"start":44.056729,"end":54.898562,"text":"この映像はシリコン型 2.5D の教材であり、構造の異なる CoWoS の全方式を表すものではありません。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":66.780979,"text":"ダイの縁に沿って飛び、HBM へ向かう並列配線を追います。","chapterIndex":2,"sentenceIndex":0},{"start":66.960979,"end":74.754604,"text":"帯域幅は一本の高速化だけでなく、多数の経路の協調でも得られます。","chapterIndex":2,"sentenceIndex":1},{"start":74.934604,"end":77.942104,"text":"光は接続の表現です。","chapterIndex":2,"sentenceIndex":2},{"start":78.122104,"end":84.923667,"text":"実設計では寄生成分、クロストーク、タイミング余裕も評価します。","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":95.260854,"text":"組立前のダイ、中間層、基板を分けます。","chapterIndex":3,"sentenceIndex":0},{"start":95.440854,"end":107.325271,"text":"部品検査、搭載、アンダーフィル、接合後試験を計画し、高価な組立の最後まで欠陥を持ち越さないようにします。","chapterIndex":3,"sentenceIndex":1},{"start":107.505271,"end":116.061917,"text":"ここでは概念を示し、実際の順序や材料条件は認定工程に従います。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":126.549229,"text":"層を分けてダイ接点、配線、シリコン貫通ビアを探します。","chapterIndex":4,"sentenceIndex":0},{"start":126.729229,"end":136.380938,"text":"HBM 内の積層接続と、インターポーザーから基板へ向かう接続は別の構造です。","chapterIndex":4,"sentenceIndex":1},{"start":136.560937,"end":144.168604,"text":"隣のダイへ向かうデータと、基板へ向かう電源・外部接続を分けて追いましょう。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":154.859854,"text":"メモリーから演算部へ、そして戻るデータを追います。","chapterIndex":5,"sentenceIndex":0},{"start":155.039854,"end":161.80925,"text":"毎秒の量、一ビットのエネルギー、最悪遅延の三点を考えます。","chapterIndex":5,"sentenceIndex":1},{"start":161.98925,"end":169.768771,"text":"距離短縮は有利でも、システム全体の省電力は自動的には決まりません。","chapterIndex":5,"sentenceIndex":2},{"start":169.948771,"end":173.993896,"text":"処理内容や制御回路も影響します。","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":187.526292,"text":"熱は演算ダイから界面材料を通り、上の冷却構造へ移動します。","chapterIndex":6,"sentenceIndex":0},{"start":187.706292,"end":191.509396,"text":"周囲のメモリーにも温度制限があります。","chapterIndex":6,"sentenceIndex":1},{"start":191.689396,"end":197.058604,"text":"赤色は概念上の熱点で測定値ではありません。","chapterIndex":6,"sentenceIndex":2},{"start":197.238604,"end":205.0115,"text":"冷却方式を比べるときは電力、周囲環境、接触条件を揃えます。","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":217.536,"text":"検査では外観、接点画像、電気試験が別々の問いに答えます。","chapterIndex":7,"sentenceIndex":0},{"start":217.716,"end":228.675104,"text":"きれいな X 線像だけでは全信号の動作を証明できず、電気試験合格だけでは寿命を保証できません。","chapterIndex":7,"sentenceIndex":1},{"start":228.855104,"end":234.757521,"text":"位置、試験結果、製造ロットを関連付けて改善します。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":248.207521,"text":"上空へ戻り、メモリー増設、配線短縮、作りやすさの関係を比べます。","chapterIndex":8,"sentenceIndex":0},{"start":248.387521,"end":254.960229,"text":"面積、反り、給電、冷却はコストと歩留まりに影響します。","chapterIndex":8,"sentenceIndex":1},{"start":255.140229,"end":264.592125,"text":"空間をすべて埋めることではなく、適切なシステムを成立させることが中間層の価値です。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":283.503479,"text":"要求定義、演算と HBM の配置、配線と電源、組立計画、熱と信頼性の検証を見渡します。","chapterIndex":9,"sentenceIndex":0},{"start":283.683479,"end":295.006021,"text":"データの出発点、熱の出口、確認すべき接点を指せれば、このパッケージの要点を理解しています。","chapterIndex":9,"sentenceIndex":1}]},"ko":{"file":"assets/packaging-tour-v33/audio/interposer.ko.m4a","sha256":"826282062d54474ec0ee52f8822cf7af4b543b8c605c951e47e59a29fb90ddf1","cues":[{"start":0.35,"end":8.936896,"text":"위에서 보면 연산 다이 옆에 HBM 메모리 스택이 있고, 아래에는 실리콘 인터포저가 있습니다.","chapterIndex":0,"sentenceIndex":0},{"start":9.116896,"end":13.502979,"text":"작은 패키지를 도시처럼 확대한 교육 장면입니다.","chapterIndex":0,"sentenceIndex":1},{"start":13.682979,"end":20.741083,"text":"먼저 계산, 저장, 연결을 담당하는 부분을 구분한 뒤 세부 구조로 내려갑니다.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":34.617771,"text":"다이, 인터포저, 패키지 기판을 구분합니다.","chapterIndex":1,"sentenceIndex":0},{"start":34.797771,"end":41.298563,"text":"인터포저는 고밀도 다이 간 배선을, 기판은 회로 보드 연결을 담당합니다.","chapterIndex":1,"sentenceIndex":1},{"start":41.478563,"end":46.389646,"text":"여기서는 실리콘 인터포저 기반 2.5D를 보여 줍니다.","chapterIndex":1,"sentenceIndex":2},{"start":46.569646,"end":52.652792,"text":"구조가 다른 모든 CoWoS 변형을 하나의 실리콘 판으로 이해하면 안 됩니다.","chapterIndex":1,"sentenceIndex":3},{"start":60.35,"end":65.943521,"text":"다이 가장자리를 따라 HBM으로 이어지는 병렬 배선을 봅니다.","chapterIndex":2,"sentenceIndex":0},{"start":66.123521,"end":71.648021,"text":"대역폭은 한 선의 속도뿐 아니라 여러 채널의 협력으로 확보됩니다.","chapterIndex":2,"sentenceIndex":1},{"start":71.828021,"end":76.842542,"text":"빛은 연결 관계를 나타내며 전자의 실제 속도가 아닙니다.","chapterIndex":2,"sentenceIndex":2},{"start":77.022542,"end":81.736333,"text":"기생 성분, 누화, 타이밍 여유도 검토해야 합니다.","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":95.028875,"text":"조립 전 다이, 인터포저, 기판을 분리해 봅니다.","chapterIndex":3,"sentenceIndex":0},{"start":95.208875,"end":105.843354,"text":"부품 검사와 배치, 언더필, 접합 후 시험을 계획하면 비싼 조립을 마친 뒤 결함을 발견하는 위험을 줄일 수 있습니다.","chapterIndex":3,"sentenceIndex":1},{"start":106.023354,"end":111.781042,"text":"실제 순서와 재료 조건은 검증된 제조 공정에 따라 달라집니다.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":127.349375,"text":"펼친 층에서 다이 접점, 인터포저 배선, 실리콘 관통 비아를 찾습니다.","chapterIndex":4,"sentenceIndex":0},{"start":127.529375,"end":135.075104,"text":"HBM 스택 내부의 수직 연결과 인터포저에서 기판으로 내려가는 연결은 서로 다릅니다.","chapterIndex":4,"sentenceIndex":1},{"start":135.255104,"end":142.627187,"text":"이웃 다이로 향하는 데이터와 기판으로 이어지는 전원·외부 연결을 각각 따라가 보세요.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":155.029104,"text":"메모리에서 연산부로 갔다 돌아오는 데이터를 따라갑니다.","chapterIndex":5,"sentenceIndex":0},{"start":155.209104,"end":160.988167,"text":"초당 데이터량, 비트당 에너지, 최악 지연을 함께 물어야 합니다.","chapterIndex":5,"sentenceIndex":1},{"start":161.168167,"end":168.597167,"text":"짧은 연결이 도움이 되지만 가까이 배치했다고 시스템 전력이 반드시 줄지는 않습니다.","chapterIndex":5,"sentenceIndex":2},{"start":168.777167,"end":172.516687,"text":"작업 부하와 제어기도 결과에 영향을 줍니다.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":185.959042,"text":"연산 다이의 열은 계면 재료를 거쳐 위쪽 냉각 구조로 이동합니다.","chapterIndex":6,"sentenceIndex":0},{"start":186.139042,"end":189.382229,"text":"주변 메모리의 온도 한계도 중요합니다.","chapterIndex":6,"sentenceIndex":1},{"start":189.562229,"end":194.145729,"text":"붉은 영역은 개념적 열점이며 측정 온도가 아닙니다.","chapterIndex":6,"sentenceIndex":2},{"start":194.325729,"end":201.119062,"text":"냉각안을 비교할 때는 전력, 주변 환경, 접촉 조건을 같게 해야 합니다.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":216.777542,"text":"외관 검사, 접합부 영상, 전기 시험은 서로 다른 문제를 확인합니다.","chapterIndex":7,"sentenceIndex":0},{"start":216.957542,"end":223.128521,"text":"깨끗한 X선 영상이 모든 신호의 정상 작동을 증명하지는 않습니다.","chapterIndex":7,"sentenceIndex":1},{"start":223.308521,"end":227.163125,"text":"전기 시험 통과도 수명을 보장하지 않습니다.","chapterIndex":7,"sentenceIndex":2},{"start":227.343125,"end":233.971563,"text":"결함 위치, 시험 결과, 공정 로트를 연결해 개선 원인을 찾습니다.","chapterIndex":7,"sentenceIndex":3},{"start":240.35,"end":246.653375,"text":"다시 올라가 메모리 추가, 배선 단축, 제조 가능성의 균형을 봅니다.","chapterIndex":8,"sentenceIndex":0},{"start":246.833375,"end":253.729125,"text":"패키지 면적, 휨, 전력 공급, 냉각은 비용과 수율에 함께 영향을 줍니다.","chapterIndex":8,"sentenceIndex":1},{"start":253.909125,"end":262.05775,"text":"인터포저의 가치는 빈 공간을 모두 채우는 것이 아니라 균형 잡힌 시스템을 만드는 데 있습니다.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":281.460812,"text":"요구 정의, 연산과 HBM 배치, 연결과 전원 설계, 조립 계획, 열·신뢰성 검증의 전체 경로를 봅니다.","chapterIndex":9,"sentenceIndex":0},{"start":281.640812,"end":291.840958,"text":"데이터가 시작되는 곳, 열이 빠져나가는 곳, 검증이 필요한 접점을 짚을 수 있다면 이 패키지의 핵심을 이해한 것입니다.","chapterIndex":9,"sentenceIndex":1}]}},"fanout":{"zh-TW":{"file":"assets/packaging-tour-v33/audio/fanout.zh-TW.m4a","sha256":"ef764e5f57443e92a2506fd43f41bb005d555cd6ad1382fdb5c68daad4d048a2","cues":[{"start":0.35,"end":8.162125,"text":"俯瞰中央晶粒，四周留出的不是浪費空間，而是扇出連接的舞台。","chapterIndex":0,"sentenceIndex":0},{"start":8.342125,"end":14.53325,"text":"重佈線層把原本密集的接點重新安排到較大的範圍。","chapterIndex":0,"sentenceIndex":1},{"start":14.71325,"end":23.702458,"text":"先看晶粒邊界，再看連線越過邊界，你就能分辨「晶片大小」和「封裝大小」。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":41.081896,"text":"下降到材質交界：硬的矽晶粒、周圍的模封材料、表面的介電層與金屬線共同形成結構。","chapterIndex":1,"sentenceIndex":0},{"start":41.261896,"end":46.785583,"text":"顏色用來辨認功能，不代表特定廠商配方。","chapterIndex":1,"sentenceIndex":1},{"start":46.965583,"end":54.79425,"text":"美感來自整齊的層次；工程難點則藏在不同材料如何一起變形。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":68.078354,"text":"沿著一個晶粒接點追到外部焊球，會遇到平面走線與跨層導孔。","chapterIndex":2,"sentenceIndex":0},{"start":68.258354,"end":76.918646,"text":"RDL 不是任意畫線：線寬、間距、回流路徑與絕緣都有限制。","chapterIndex":2,"sentenceIndex":1},{"start":77.098646,"end":84.094208,"text":"請找出哪一段在換層，哪一段在把連接位置往外展開。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":101.331729,"text":"畫面把兩種流程分開：晶粒先放好再形成重佈線，或先形成 RDL 再接上晶粒。","chapterIndex":3,"sentenceIndex":0},{"start":101.511729,"end":107.543312,"text":"兩條路都叫扇出，但良率風險出現的位置不同。","chapterIndex":3,"sentenceIndex":1},{"start":107.723312,"end":114.782146,"text":"不能只用成品外觀判斷製程；要知道昂貴晶粒在哪一步加入。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":130.201021,"text":"把薄薄的封裝拉開成分層示意，介電層隔開不同金屬層，導孔讓特定位置相通。","chapterIndex":4,"sentenceIndex":0},{"start":130.381021,"end":137.885604,"text":"這裡刻意放大厚度方便觀看，不能拿畫面比例當成製造尺寸。","chapterIndex":4,"sentenceIndex":1},{"start":138.065604,"end":144.813187,"text":"請確認相鄰的兩條線是刻意連接，還是應該保持絕緣。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":154.416958,"text":"訊號線旁的參考導體同樣重要。","chapterIndex":5,"sentenceIndex":0},{"start":154.596958,"end":161.694375,"text":"電流必須形成回路；回流路徑中斷會改變高速訊號品質。","chapterIndex":5,"sentenceIndex":1},{"start":161.874375,"end":174.286458,"text":"俯瞰時看走線是否順暢，剖面時看參考層是否連續，兩種角度一起看，才能理解佈線的真正秩序。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":185.973646,"text":"示意結構微微彎曲，提醒你材料熱膨脹不一致。","chapterIndex":6,"sentenceIndex":0},{"start":186.153646,"end":193.241104,"text":"翹曲會影響對位、接合與後續裝板，不只是看起來不平。","chapterIndex":6,"sentenceIndex":1},{"start":193.421104,"end":204.559396,"text":"動畫中的彎曲被誇張呈現；真正評估要使用量測、材料資料與有邊界條件的力學模型。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":219.352875,"text":"停在接點附近，想像晶粒輕微偏移後，原定走線能否仍落在正確位置。","chapterIndex":7,"sentenceIndex":0},{"start":219.532875,"end":225.900271,"text":"檢查必須同時照顧對位、開路、短路與界面缺陷。","chapterIndex":7,"sentenceIndex":1},{"start":226.080271,"end":233.736875,"text":"每個異常都要回到可追溯的量測，不能只憑動畫上「看起來有接到」。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":253.721479,"text":"退後看整體，扇出可以提供靈活的接點配置與薄型整合，但更多層、更密線距或更大面積也會增加製程挑戰。","chapterIndex":8,"sentenceIndex":0},{"start":253.901479,"end":263.560667,"text":"不能一概說扇出一定比較便宜；比較時必須使用相同功能、測試涵蓋與合格產出。","chapterIndex":8,"sentenceIndex":1},{"start":270.35,"end":285.401854,"text":"帶走這條路線：先定接點與尺寸需求，再選晶粒先行或 RDL 先行，接著規劃佈線、控制翹曲、完成電性與可靠度驗證。","chapterIndex":9,"sentenceIndex":0},{"start":285.581854,"end":293.839333,"text":"扇出的美感，是把擁擠的微小出口整理成有秩序、能製造也能檢查的網路。","chapterIndex":9,"sentenceIndex":1}]},"en":{"file":"assets/packaging-tour-v33/audio/fanout.en.m4a","sha256":"aab222de76e3ebb17a37f76eb0ddfa3ae91168b5488213b5e9c0b263bf9033d2","cues":[{"start":0.35,"end":2.401312,"text":"Look down at the central die.","chapterIndex":0,"sentenceIndex":0},{"start":2.581313,"end":7.511563,"text":"The surrounding area is useful routing space, not empty waste.","chapterIndex":0,"sentenceIndex":1},{"start":7.691562,"end":13.149812,"text":"Redistribution layers relocate dense die connections across a wider region.","chapterIndex":0,"sentenceIndex":2},{"start":13.329812,"end":21.672729,"text":"Compare the die outline with routes extending beyond it, and distinguish the size of the silicon from the size of its package.","chapterIndex":0,"sentenceIndex":3},{"start":30.35,"end":41.172229,"text":"Descend to the material boundaries: silicon dies, surrounding molding compound, dielectric layers and metal traces form one structure.","chapterIndex":1,"sentenceIndex":0},{"start":41.352229,"end":45.379458,"text":"Colors identify function, not a vendor recipe.","chapterIndex":1,"sentenceIndex":1},{"start":45.559458,"end":53.353167,"text":"The ordered layers create visual clarity; the engineering challenge is how different materials deform together.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":66.97,"text":"Follow a die contact to an external solder ball through planar traces and interlayer vias.","chapterIndex":2,"sentenceIndex":0},{"start":67.15,"end":76.412417,"text":"RDL is constrained routing, not arbitrary drawing: width, spacing, return paths and insulation all matter.","chapterIndex":2,"sentenceIndex":1},{"start":76.592417,"end":81.715729,"text":"Identify where the route changes layer and where it moves the connection outward.","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":99.089021,"text":"Compare two flows: place dies before building redistribution layers, or form RDL before attaching dies.","chapterIndex":3,"sentenceIndex":0},{"start":99.269021,"end":104.504854,"text":"Both are fan-out approaches, but yield risks enter at different stages.","chapterIndex":3,"sentenceIndex":1},{"start":104.684854,"end":108.396104,"text":"The final outline alone does not reveal the process.","chapterIndex":3,"sentenceIndex":2},{"start":108.576104,"end":113.786417,"text":"Ask when valuable dies enter the assembly and what has already been tested.","chapterIndex":3,"sentenceIndex":3},{"start":120.35,"end":123.548792,"text":"Open the thin package into separated layers.","chapterIndex":4,"sentenceIndex":0},{"start":123.728792,"end":129.387854,"text":"Dielectrics separate metal layers, while vias connect selected locations.","chapterIndex":4,"sentenceIndex":1},{"start":129.567854,"end":135.651042,"text":"Thickness is exaggerated for visibility and must not be read as manufacturing scale.","chapterIndex":4,"sentenceIndex":2},{"start":135.831042,"end":144.039625,"text":"Check whether adjacent routes should be connected or electrically isolated; that distinction is the purpose of the layer stack.","chapterIndex":4,"sentenceIndex":3},{"start":150.35,"end":154.183208,"text":"The reference conductor beside a signal is important too.","chapterIndex":5,"sentenceIndex":0},{"start":154.363208,"end":160.413292,"text":"Current needs a complete loop; a disrupted return path affects high-speed behavior.","chapterIndex":5,"sentenceIndex":1},{"start":160.593292,"end":166.683646,"text":"Use the overhead view to inspect routing and the section to inspect reference continuity.","chapterIndex":5,"sentenceIndex":2},{"start":166.863646,"end":172.188688,"text":"Together, the two views explain the electrical order behind the geometry.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":185.157,"text":"A slight conceptual bend highlights mismatched thermal expansion.","chapterIndex":6,"sentenceIndex":0},{"start":185.337,"end":192.198375,"text":"Warpage can affect alignment, joining and board assembly; it is more than a cosmetic defect.","chapterIndex":6,"sentenceIndex":1},{"start":192.378375,"end":194.884417,"text":"The animated bend is exaggerated.","chapterIndex":6,"sentenceIndex":2},{"start":195.064417,"end":203.586646,"text":"Evaluation requires measurements, material properties and a mechanical model with explicit boundary conditions.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":214.636125,"text":"Pause beside a contact and imagine the die shifting slightly.","chapterIndex":7,"sentenceIndex":0},{"start":214.816125,"end":217.621125,"text":"Would the intended route still land correctly?","chapterIndex":7,"sentenceIndex":1},{"start":217.801125,"end":223.619146,"text":"Inspection must address alignment, opens, shorts and interface defects.","chapterIndex":7,"sentenceIndex":2},{"start":223.799146,"end":232.472813,"text":"Each suspected issue needs traceable measurement; a visually touching animated connection is not evidence of a functional joint.","chapterIndex":7,"sentenceIndex":3},{"start":240.35,"end":251.882479,"text":"Step back: fan-out offers flexible connection placement and thin integration, while more layers, finer routing or larger area raise process demands.","chapterIndex":8,"sentenceIndex":0},{"start":252.062479,"end":254.270104,"text":"It is not automatically cheaper.","chapterIndex":8,"sentenceIndex":1},{"start":254.450104,"end":263.691667,"text":"Compare alternatives at equal function, test coverage and qualified output, rather than comparing package outlines alone.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":284.537312,"text":"Take this route with you: define connections and size, select die-first or RDL-first integration, plan routing, manage warpage and verify electrical behavior and reliability.","chapterIndex":9,"sentenceIndex":0},{"start":284.717312,"end":294.414062,"text":"Fan-out turns crowded die exits into an orderly network that must be manufacturable and inspectable, not merely visually elegant.","chapterIndex":9,"sentenceIndex":1}]},"zh-CN":{"file":"assets/packaging-tour-v33/audio/fanout.zh-CN.m4a","sha256":"0e067e9f6f7fb1bfc26f0205e9d03f0ad887789f30340b210b2dd316200694cc","cues":[{"start":0.35,"end":8.779083,"text":"俯瞰中央晶粒，四周留出的不是浪费空间，而是扇出连接的舞台。","chapterIndex":0,"sentenceIndex":0},{"start":8.959083,"end":15.335104,"text":"重布线层把原本密集的接点重新安排到较大的范围。","chapterIndex":0,"sentenceIndex":1},{"start":15.515104,"end":25.118875,"text":"先看晶粒边界，再看连线越过边界，你就能分辨芯片大小和封装大小。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":41.018583,"text":"下降到材质交界：硬的硅晶粒、周围的模封材料、表面的介电层与金属线共同形成结构。","chapterIndex":1,"sentenceIndex":0},{"start":41.198583,"end":46.37075,"text":"颜色用来辨认功能，不代表特定厂商配方。","chapterIndex":1,"sentenceIndex":1},{"start":46.55075,"end":54.164417,"text":"美感来自整齐的层次；工程难点则藏在不同材料如何一起变形。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":68.059083,"text":"沿着一个晶粒接点追到外部焊球，会遇到平面走线与跨层导孔。","chapterIndex":2,"sentenceIndex":0},{"start":68.239083,"end":76.992708,"text":"RDL 不是任意画线：线宽、间距、回流路径与绝缘都有限制。","chapterIndex":2,"sentenceIndex":1},{"start":77.172708,"end":83.770354,"text":"请找出哪一段在换层，哪一段在把连接位置往外展开。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":101.704792,"text":"画面把两种流程分开：晶粒先放好再形成重布线，或先形成 RDL 再接上晶粒。","chapterIndex":3,"sentenceIndex":0},{"start":101.884792,"end":107.516958,"text":"两条路都叫扇出，但良率风险出现的位置不同。","chapterIndex":3,"sentenceIndex":1},{"start":107.696958,"end":114.546583,"text":"不能只用成品外观判断工艺；要知道昂贵晶粒在哪一步加入。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":130.073458,"text":"把薄薄的封装拉开成分层示意，介电层隔开不同金属层，导孔让特定位置相通。","chapterIndex":4,"sentenceIndex":0},{"start":130.253458,"end":137.370833,"text":"这里刻意放大厚度方便观看，不能拿画面比例当成制造尺寸。","chapterIndex":4,"sentenceIndex":1},{"start":137.550833,"end":144.195417,"text":"请确认相邻的两条线是刻意连接，还是应该保持绝缘。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":154.154,"text":"信号线旁的参考导体同样重要。","chapterIndex":5,"sentenceIndex":0},{"start":154.334,"end":161.180729,"text":"电流必须形成回路；回流路径中断会改变高速信号质量。","chapterIndex":5,"sentenceIndex":1},{"start":161.360729,"end":173.548229,"text":"俯瞰时看走线是否顺畅，剖面时看参考层是否连续，两种角度一起看，才能理解布线的真正秩序。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":185.768875,"text":"示意结构微微弯曲，提醒你材料热膨胀不一致。","chapterIndex":6,"sentenceIndex":0},{"start":185.948875,"end":193.025125,"text":"翘曲会影响对位、接合与后续装板，不只是看起来不平。","chapterIndex":6,"sentenceIndex":1},{"start":193.205125,"end":203.548396,"text":"动画中的弯曲被夸张呈现；真正评估要使用测量、材料数据与有边界条件的力学模型。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":219.886562,"text":"停在接点附近，想象晶粒轻微偏移后，原定走线能否仍落在正确位置。","chapterIndex":7,"sentenceIndex":0},{"start":220.066563,"end":226.665208,"text":"检查必须同时照顾对位、开路、短路与界面缺陷。","chapterIndex":7,"sentenceIndex":1},{"start":226.845208,"end":235.041646,"text":"每个异常都要回到可追溯的测量，不能只凭动画上看起来有接到。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":253.94675,"text":"退后看整体，扇出可以提供灵活的接点配置与薄型整合，但更多层、更密线距或更大面积也会增加工艺挑战。","chapterIndex":8,"sentenceIndex":0},{"start":254.12675,"end":263.777229,"text":"不能一概说扇出一定比较便宜；比较时必须使用相同功能、测试覆盖与合格产出。","chapterIndex":8,"sentenceIndex":1},{"start":270.35,"end":287.336854,"text":"带走这条路线：先定接点与尺寸需求，再选晶粒先行或 RDL 先行，接着规划布线、控制翘曲、完成电性与可靠性验证。","chapterIndex":9,"sentenceIndex":0},{"start":287.516854,"end":296.130562,"text":"扇出的美感，是把拥挤的微小出口整理成有秩序、能制造也能检查的网络。","chapterIndex":9,"sentenceIndex":1}]},"ja":{"file":"assets/packaging-tour-v33/audio/fanout.ja.m4a","sha256":"2136849d30024369916fd22b2ea58a76919fcd9b4ea741d18d3940b76a80c7dd","cues":[{"start":0.35,"end":7.479771,"text":"中央のダイの周囲は無駄な空間ではなく、配線を広げる場所です。","chapterIndex":0,"sentenceIndex":0},{"start":7.659771,"end":14.415292,"text":"再配線層は密集した接点を広い範囲へ配置し直します。","chapterIndex":0,"sentenceIndex":1},{"start":14.595292,"end":24.12075,"text":"ダイの輪郭と、その外へ伸びる線を比べて、シリコンとパッケージの大きさを区別しましょう。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":37.729563,"text":"シリコン、周囲の封止材、絶縁層、金属配線の境界へ降ります。","chapterIndex":1,"sentenceIndex":0},{"start":37.909562,"end":44.147896,"text":"色は機能を区別するためで、メーカーの材料配合ではありません。","chapterIndex":1,"sentenceIndex":1},{"start":44.327896,"end":54.478875,"text":"整った層が見た目を明快にし、異なる材料が一緒に変形することが技術上の課題になります。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":67.45,"text":"ダイ接点から外部はんだボールまで、平面配線と層間ビアを追います。","chapterIndex":2,"sentenceIndex":0},{"start":67.63,"end":76.968187,"text":"RDL は自由な線画ではなく、線幅、間隔、帰路、絶縁の制約を受けます。","chapterIndex":2,"sentenceIndex":1},{"start":77.148188,"end":84.020167,"text":"層を変える場所と、接続位置を外側へ広げる場所を探してください。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":100.490062,"text":"ダイを先に置いて再配線する工程と、RDL を先に作ってダイを載せる工程を比べます。","chapterIndex":3,"sentenceIndex":0},{"start":100.670063,"end":107.420312,"text":"どちらもファンアウトですが、歩留まりのリスクが現れる段階は異なります。","chapterIndex":3,"sentenceIndex":1},{"start":107.600313,"end":115.053875,"text":"完成形だけで判断せず、高価なダイをいつ投入するか確認します。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":124.263479,"text":"薄いパッケージを層ごとに開きます。","chapterIndex":4,"sentenceIndex":0},{"start":124.443479,"end":132.049375,"text":"絶縁層が金属層を分け、ビアが必要な点だけを接続します。","chapterIndex":4,"sentenceIndex":1},{"start":132.229375,"end":137.921312,"text":"厚みは見やすく拡大しており製造寸法ではありません。","chapterIndex":4,"sentenceIndex":2},{"start":138.101313,"end":144.012208,"text":"隣の線をつなぐべきか、絶縁すべきかを確認します。","chapterIndex":4,"sentenceIndex":3},{"start":150.35,"end":155.149292,"text":"信号の近くにある基準導体も重要です。","chapterIndex":5,"sentenceIndex":0},{"start":155.329292,"end":163.982812,"text":"電流には閉じた経路が必要で、帰路の不連続は高速信号に影響します。","chapterIndex":5,"sentenceIndex":1},{"start":164.162813,"end":175.301958,"text":"上から配線を、断面から基準層の連続性を見て、形の背後にある電気的な秩序を理解します。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":185.358313,"text":"概念的な曲がりで熱膨張の違いを示します。","chapterIndex":6,"sentenceIndex":0},{"start":185.538312,"end":193.941417,"text":"反りは位置合わせ、接合、基板実装に影響し、外観だけの問題ではありません。","chapterIndex":6,"sentenceIndex":1},{"start":194.121417,"end":197.392313,"text":"映像は変形を誇張しています。","chapterIndex":6,"sentenceIndex":2},{"start":197.572313,"end":205.927104,"text":"評価には測定、材料特性、境界条件を定めた力学モデルが必要です。","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":217.696958,"text":"接点で止まり、ダイが少しずれたら配線が正しく届くか考えます。","chapterIndex":7,"sentenceIndex":0},{"start":217.876958,"end":224.836917,"text":"位置、断線、短絡、界面欠陥を検査する必要があります。","chapterIndex":7,"sentenceIndex":1},{"start":225.016917,"end":234.721688,"text":"映像で接触して見えることは接合品質の証拠ではなく、追跡可能な測定が必要です。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":254.4505,"text":"全体を見ると、ファンアウトは柔軟な接点配置と薄型化を可能にしますが、多層化、微細化、大面積化は工程を難しくします。","chapterIndex":8,"sentenceIndex":0},{"start":254.6305,"end":258.085521,"text":"必ず安価になるわけではありません。","chapterIndex":8,"sentenceIndex":1},{"start":258.265521,"end":264.213958,"text":"同じ機能、試験範囲、良品出荷を条件に比較します。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":284.525479,"text":"接点と寸法の要求から始め、ダイ先行か RDL 先行かを選び、配線、反り対策、電気・信頼性検証へ進みます。","chapterIndex":9,"sentenceIndex":0},{"start":284.705479,"end":294.167312,"text":"密集する出口を、製造でき検査できる整ったネットワークへ変えることがファンアウトの美しさです。","chapterIndex":9,"sentenceIndex":1}]},"ko":{"file":"assets/packaging-tour-v33/audio/fanout.ko.m4a","sha256":"1d45dba56026bc842a8bf85e61fe55bfbd0a439bfb59fcd2bc0ef60a23334901","cues":[{"start":0.35,"end":6.034917,"text":"중앙 다이 주변은 빈 낭비 공간이 아니라 배선을 펼치는 영역입니다.","chapterIndex":0,"sentenceIndex":0},{"start":6.214917,"end":11.131625,"text":"재배선층은 조밀한 다이 접점을 더 넓은 범위로 옮깁니다.","chapterIndex":0,"sentenceIndex":1},{"start":11.311625,"end":19.112729,"text":"다이의 경계와 그 밖으로 나가는 선을 비교하면 실리콘 크기와 패키지 크기를 구분할 수 있습니다.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":37.089146,"text":"실리콘, 주변 몰딩 재료, 절연층, 금속 배선의 경계로 내려갑니다.","chapterIndex":1,"sentenceIndex":0},{"start":37.269146,"end":42.719729,"text":"색은 기능 구분용이며 특정 회사의 재료 조성을 뜻하지 않습니다.","chapterIndex":1,"sentenceIndex":1},{"start":42.899729,"end":52.095021,"text":"정돈된 층은 시각적 아름다움을 만들지만, 서로 다른 재료가 함께 변형되는 현상은 공학적 과제입니다.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":66.479,"text":"다이 접점에서 외부 솔더볼까지 평면 배선과 층간 비아를 따라갑니다.","chapterIndex":2,"sentenceIndex":0},{"start":66.659,"end":70.005458,"text":"RDL은 자유롭게 그리는 선이 아닙니다.","chapterIndex":2,"sentenceIndex":1},{"start":70.185458,"end":75.406875,"text":"선폭, 간격, 귀환 경로, 절연 조건이 중요합니다.","chapterIndex":2,"sentenceIndex":2},{"start":75.586875,"end":81.658854,"text":"층이 바뀌는 부분과 연결 위치가 바깥으로 이동하는 부분을 찾아보세요.","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":98.88625,"text":"다이를 먼저 놓고 RDL을 만드는 공정과 RDL을 먼저 만들고 다이를 붙이는 공정을 비교합니다.","chapterIndex":3,"sentenceIndex":0},{"start":99.06625,"end":103.974292,"text":"둘 다 팬아웃이지만 수율 위험이 나타나는 단계가 다릅니다.","chapterIndex":3,"sentenceIndex":1},{"start":104.154292,"end":111.307083,"text":"완성된 외형만 보지 말고 값비싼 다이를 어느 단계에서 투입하는지 확인해야 합니다.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":123.361083,"text":"얇은 패키지를 층별로 펼칩니다.","chapterIndex":4,"sentenceIndex":0},{"start":123.541083,"end":128.951937,"text":"절연층은 금속층을 분리하고 비아는 필요한 지점만 연결합니다.","chapterIndex":4,"sentenceIndex":1},{"start":129.131937,"end":134.584146,"text":"두께는 보기 쉽게 과장했으므로 제조 치수로 해석하면 안 됩니다.","chapterIndex":4,"sentenceIndex":2},{"start":134.764146,"end":140.051688,"text":"인접한 배선이 연결되어야 하는지 절연되어야 하는지 확인합니다.","chapterIndex":4,"sentenceIndex":3},{"start":150.35,"end":153.465833,"text":"신호 옆의 기준 도체도 중요합니다.","chapterIndex":5,"sentenceIndex":0},{"start":153.645833,"end":160.745396,"text":"전류는 완전한 회로를 이루어야 하며 귀환 경로의 단절은 고속 신호에 영향을 줍니다.","chapterIndex":5,"sentenceIndex":1},{"start":160.925396,"end":166.510354,"text":"위에서는 배선을, 단면에서는 기준층의 연속성을 확인하세요.","chapterIndex":5,"sentenceIndex":2},{"start":166.690354,"end":170.671583,"text":"두 시점이 배선의 전기적 질서를 설명합니다.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":185.189875,"text":"개념적인 굽힘은 재료 간 열팽창 차이를 보여 줍니다.","chapterIndex":6,"sentenceIndex":0},{"start":185.369875,"end":192.28525,"text":"휨은 정렬, 접합, 보드 실장에 영향을 주므로 단순한 외관 문제가 아닙니다.","chapterIndex":6,"sentenceIndex":1},{"start":192.46525,"end":195.767292,"text":"애니메이션의 변형은 과장되어 있습니다.","chapterIndex":6,"sentenceIndex":2},{"start":195.947292,"end":202.742625,"text":"평가에는 측정과 재료 특성, 경계 조건을 정한 역학 모델이 필요합니다.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":216.690833,"text":"접점 옆에서 다이가 조금 이동하면 배선이 올바르게 닿을지 생각해 봅니다.","chapterIndex":7,"sentenceIndex":0},{"start":216.870833,"end":222.467125,"text":"정렬, 단선, 단락, 계면 결함을 함께 검사해야 합니다.","chapterIndex":7,"sentenceIndex":1},{"start":222.647125,"end":230.526917,"text":"화면에서 붙어 보인다는 사실은 정상 접합의 증거가 아니며 추적 가능한 측정이 필요합니다.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":252.115729,"text":"전체를 보면 팬아웃은 유연한 접점 배치와 얇은 통합을 제공하지만 층수 증가, 미세 배선, 면적 확대는 공정 난도를 높입니다.","chapterIndex":8,"sentenceIndex":0},{"start":252.295729,"end":254.930062,"text":"항상 더 저렴한 것은 아닙니다.","chapterIndex":8,"sentenceIndex":1},{"start":255.110062,"end":260.977021,"text":"같은 기능, 시험 범위, 양품 출하량을 기준으로 비교해야 합니다.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":281.859208,"text":"접점과 크기 요구를 정하고, 다이 선행 또는 RDL 선행을 선택한 뒤 배선, 휨 관리, 전기·신뢰성 검증으로 이어집니다.","chapterIndex":9,"sentenceIndex":0},{"start":282.039208,"end":290.883708,"text":"복잡한 다이 출구를 제조하고 검사할 수 있는 질서 있는 네트워크로 만드는 것이 팬아웃의 아름다움입니다.","chapterIndex":9,"sentenceIndex":1}]}},"hybrid":{"zh-TW":{"file":"assets/packaging-tour-v33/audio/hybrid.zh-TW.m4a","sha256":"9ff4f3dd5af0d43d8a4df74b3013851587822b264162f256504d72113532d0ae","cues":[{"start":0.35,"end":11.00675,"text":"先俯瞰，再緩緩轉成斜視：原本並排的功能可以上下堆疊，縮短某些晶粒間的路徑。","chapterIndex":0,"sentenceIndex":0},{"start":11.18675,"end":19.057917,"text":"這不是把完整電路板直接疊起來，而是在精密控制的界面接合晶粒。","chapterIndex":0,"sentenceIndex":1},{"start":19.237917,"end":23.811396,"text":"先數清有幾層，再找每一層的角色。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":41.286437,"text":"上層可以放運算或記憶功能，下層可以承接其他電路與連接；具體配置取決於架構。","chapterIndex":1,"sentenceIndex":0},{"start":41.466437,"end":45.638604,"text":"堆疊不保證每層都使用同一製程。","chapterIndex":1,"sentenceIndex":1},{"start":45.818604,"end":54.246542,"text":"這裡是通用教學模型，不是 SoIC 或 Foveros 特定產品的內部配置圖。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":70.978167,"text":"靠近界面：銅接點建立電性連接，周圍介電表面也參與接合，這就是混合鍵合的關鍵。","chapterIndex":2,"sentenceIndex":0},{"start":71.158167,"end":83.408604,"text":"不要把它畫成一排大型焊球；焊料微凸塊與直接混合鍵合是不同的互連方式，適用限制也不同。","chapterIndex":2,"sentenceIndex":1},{"start":90.35,"end":99.288958,"text":"讓兩片晶粒暫時分離，想像任何微粒或表面不平都可能留在接合界面。","chapterIndex":3,"sentenceIndex":0},{"start":99.468958,"end":106.4745,"text":"表面準備、潔淨度、平坦度與對位精度共同決定品質。","chapterIndex":3,"sentenceIndex":1},{"start":106.6545,"end":114.338313,"text":"動畫把動作放慢是為了看懂原理，不提供清洗配方或製程溫度。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":128.427604,"text":"分層示意中的接合距離雖短，資料仍要經過晶粒內部電路與佈線。","chapterIndex":4,"sentenceIndex":0},{"start":128.607604,"end":134.948104,"text":"垂直連接只解決路徑的一部分，不會讓邏輯延遲消失。","chapterIndex":4,"sentenceIndex":1},{"start":135.128104,"end":141.588937,"text":"找出跨越接合面的那一步，再把它放回完整的訊號鏈。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":159.111229,"text":"密集接點能讓相鄰層交換更多資訊，但架構必須真的用得上這些連接。","chapterIndex":5,"sentenceIndex":0},{"start":159.291229,"end":168.088021,"text":"先決定資料分工，再規劃接點與供電，不要先堆出最多接點才找用途。","chapterIndex":5,"sentenceIndex":1},{"start":168.268021,"end":174.608708,"text":"畫面中的流動是資訊關係示意，沒有宣稱特定速度。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":183.692958,"text":"從側面看熱往外走的路徑。","chapterIndex":6,"sentenceIndex":0},{"start":183.872958,"end":191.0185,"text":"不同層的發熱位置、界面熱阻與散熱器位置共同影響溫度。","chapterIndex":6,"sentenceIndex":1},{"start":191.1985,"end":200.684625,"text":"不能認為堆疊越高就越好；把最熱的電路放在哪裡，是一開始就要解決的架構問題。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":218.972229,"text":"被其他晶粒蓋住的接點不容易再直接碰到，因此要預先設計測試存取。","chapterIndex":7,"sentenceIndex":0},{"start":219.152229,"end":225.90675,"text":"組裝前篩選、接合後連通檢查與系統測試各有任務。","chapterIndex":7,"sentenceIndex":1},{"start":226.08675,"end":233.831396,"text":"通過一次測試不是永久保證；要把涵蓋率與剩餘風險說清楚。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":249.247104,"text":"拉開到整體視角，高密度整合會同時提高界面品質與測試規劃的重要性。","chapterIndex":8,"sentenceIndex":0},{"start":249.427104,"end":256.362708,"text":"已接合的晶粒未必能經濟地拆換，所以前段選別更有價值。","chapterIndex":8,"sentenceIndex":1},{"start":256.542708,"end":264.381083,"text":"比較方案時，要連同良品成本、熱條件與返修能力一起看。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":280.821667,"text":"最後的路線是功能分層、界面設計、表面準備、對位接合、可測試性與散熱驗證。","chapterIndex":9,"sentenceIndex":0},{"start":281.001667,"end":294.009604,"text":"記住：3D 的重點不是把樓蓋高，而是讓最需要溝通的功能靠近，同時讓電流、熱與測試都有可靠出口。","chapterIndex":9,"sentenceIndex":1}]},"en":{"file":"assets/packaging-tour-v33/audio/hybrid.en.m4a","sha256":"f6ee7eefcc79ee6a491fbbcc3fae93a09e5c33639bc8493a8292c828672269b7","cues":[{"start":0.35,"end":9.757354,"text":"Begin overhead, then tilt: functions can be stacked rather than placed side by side, shortening selected die-to-die routes.","chapterIndex":0,"sentenceIndex":0},{"start":9.937354,"end":12.629833,"text":"This is not a stack of circuit boards.","chapterIndex":0,"sentenceIndex":1},{"start":12.809833,"end":16.130521,"text":"Dies meet at carefully controlled interfaces.","chapterIndex":0,"sentenceIndex":2},{"start":16.310521,"end":22.213979,"text":"Count the layers and identify what each layer contributes before inspecting the bond.","chapterIndex":0,"sentenceIndex":3},{"start":30.35,"end":36.916812,"text":"Upper and lower dies can divide compute, memory and connection functions in different ways.","chapterIndex":1,"sentenceIndex":0},{"start":37.096812,"end":40.285167,"text":"Their process technologies need not match.","chapterIndex":1,"sentenceIndex":1},{"start":40.465167,"end":48.031792,"text":"This is a generic teaching model, not an internal floorplan of a particular SoIC or Foveros product.","chapterIndex":1,"sentenceIndex":2},{"start":48.211792,"end":51.995208,"text":"Architecture determines which functions belong together.","chapterIndex":1,"sentenceIndex":3},{"start":60.35,"end":69.409063,"text":"Approach the interface: copper contacts provide electrical connections while surrounding dielectric surfaces also bond.","chapterIndex":2,"sentenceIndex":0},{"start":69.589062,"end":72.637,"text":"That combination defines hybrid bonding.","chapterIndex":2,"sentenceIndex":1},{"start":72.817,"end":75.860687,"text":"Do not picture a row of large solder balls.","chapterIndex":2,"sentenceIndex":2},{"start":76.040688,"end":83.986542,"text":"Solder microbumps and direct hybrid bonding are different interconnect approaches with different integration constraints.","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":95.882083,"text":"Separate the dies and imagine a particle or uneven surface trapped between them.","chapterIndex":3,"sentenceIndex":0},{"start":96.062083,"end":103.680917,"text":"Surface preparation, cleanliness, flatness and alignment work together to determine bond quality.","chapterIndex":3,"sentenceIndex":1},{"start":103.860917,"end":111.792438,"text":"The motion is slowed to explain the principle; it is not a cleaning recipe or a manufacturing temperature schedule.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":126.795083,"text":"The bond interface is short, but data still traverses circuits and wiring within each die.","chapterIndex":4,"sentenceIndex":0},{"start":126.975083,"end":133.366833,"text":"Vertical connectivity solves only part of the path; it does not remove logic delay.","chapterIndex":4,"sentenceIndex":1},{"start":133.546833,"end":140.6175,"text":"Identify the crossing between dies, then place that crossing back into the complete signal chain.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":158.06125,"text":"Dense contacts can support richer communication between layers, but the architecture must make use of them.","chapterIndex":5,"sentenceIndex":0},{"start":158.24125,"end":163.402625,"text":"Define the division of data and work before allocating contacts and power.","chapterIndex":5,"sentenceIndex":1},{"start":163.582625,"end":166.663771,"text":"More connections are not a goal by themselves.","chapterIndex":5,"sentenceIndex":2},{"start":166.843771,"end":173.071542,"text":"Animated movement shows information relationships, not a claimed transfer speed.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":183.659708,"text":"From the side, follow heat out of the stack.","chapterIndex":6,"sentenceIndex":0},{"start":183.839708,"end":190.561479,"text":"Heat-source location, interface resistance and cooler placement jointly affect temperature.","chapterIndex":6,"sentenceIndex":1},{"start":190.741479,"end":193.806896,"text":"A taller stack is not automatically better.","chapterIndex":6,"sentenceIndex":2},{"start":193.986896,"end":202.538521,"text":"Where the hottest circuits belong is an architectural decision to make early, not a problem to postpone until assembly.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":218.590292,"text":"Contacts become difficult to reach after another die covers them, so test access must be designed in advance.","chapterIndex":7,"sentenceIndex":0},{"start":218.770292,"end":225.442917,"text":"Pre-assembly screening, post-bond connectivity and system testing serve different purposes.","chapterIndex":7,"sentenceIndex":1},{"start":225.622917,"end":232.412229,"text":"One passing test is not a permanent guarantee; coverage and remaining risk must be explicit.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":246.653958,"text":"Zoom out: dense integration makes interface quality and test planning more important.","chapterIndex":8,"sentenceIndex":0},{"start":246.833958,"end":253.509021,"text":"Bonded dies may not be economical to replace, increasing the value of earlier screening.","chapterIndex":8,"sentenceIndex":1},{"start":253.689021,"end":262.999833,"text":"Compare solutions using cost per good unit, thermal conditions and repair options together, rather than connection density alone.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":281.196042,"text":"The route is functional partitioning, interface design, surface preparation, alignment, bonding, testability and thermal verification.","chapterIndex":9,"sentenceIndex":0},{"start":281.376042,"end":284.740396,"text":"The aim of 3D is not merely a taller building.","chapterIndex":9,"sentenceIndex":1},{"start":284.920396,"end":293.124312,"text":"It is to bring communicating functions closer while preserving dependable paths for electricity, heat and testing.","chapterIndex":9,"sentenceIndex":2}]},"zh-CN":{"file":"assets/packaging-tour-v33/audio/hybrid.zh-CN.m4a","sha256":"5aa9c7763e9a420d49d06ad0c1a36815dbc457e424cec6bcd5ea0ddc8cbb91b0","cues":[{"start":0.35,"end":11.703125,"text":"先俯瞰，再缓缓转成斜视：原本并排的功能可以上下堆叠，缩短某些晶粒间的路径。","chapterIndex":0,"sentenceIndex":0},{"start":11.883125,"end":19.988542,"text":"这不是把完整电路板直接叠起来，而是在精密控制的界面接合晶粒。","chapterIndex":0,"sentenceIndex":1},{"start":20.168542,"end":24.925646,"text":"先数清有几层，再找每一层的角色。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":41.694187,"text":"上层可以放计算或存储功能，下层可以承接其他电路与连接；具体配置取决于架构。","chapterIndex":1,"sentenceIndex":0},{"start":41.874187,"end":45.863229,"text":"堆叠不保证每层都使用同一工艺。","chapterIndex":1,"sentenceIndex":1},{"start":46.043229,"end":54.194938,"text":"这里是通用教学模型，不是 SoIC 或 Foveros 特定产品的内部配置图。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":71.739271,"text":"靠近界面：铜接点建立电性连接，周围介电表面也参与接合，这就是混合键合的关键。","chapterIndex":2,"sentenceIndex":0},{"start":71.919271,"end":84.590354,"text":"不要把它画成一排大型焊球；焊料微凸块与直接混合键合是不同的互连方式，适用限制也不同。","chapterIndex":2,"sentenceIndex":1},{"start":90.35,"end":99.652146,"text":"让两片晶粒暂时分离，想象任何微粒或表面不平都可能留在接合界面。","chapterIndex":3,"sentenceIndex":0},{"start":99.832146,"end":106.836729,"text":"表面准备、洁净度、平坦度与对位精度共同决定质量。","chapterIndex":3,"sentenceIndex":1},{"start":107.016729,"end":114.826583,"text":"动画把动作放慢是为了看懂原理，不提供清洗配方或工艺温度。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":128.433771,"text":"分层示意中的接合距离虽短，数据仍要经过晶粒内部电路与布线。","chapterIndex":4,"sentenceIndex":0},{"start":128.613771,"end":135.296,"text":"垂直连接只解决路径的一部分，不会让逻辑延迟消失。","chapterIndex":4,"sentenceIndex":1},{"start":135.476,"end":142.156062,"text":"找出跨越接合面的那一步，再把它放回完整的信号链。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":158.480354,"text":"密集接点能让相邻层交换更多信息，但架构必须真的用得上这些连接。","chapterIndex":5,"sentenceIndex":0},{"start":158.660354,"end":167.485208,"text":"先决定数据分工，再规划接点与供电，不要先堆出最多接点才找用途。","chapterIndex":5,"sentenceIndex":1},{"start":167.665208,"end":173.702625,"text":"画面中的流动是信息关系示意，没有宣称特定速度。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":183.753646,"text":"从侧面看热往外走的路径。","chapterIndex":6,"sentenceIndex":0},{"start":183.933646,"end":191.154792,"text":"不同层的发热位置、界面热阻与散热器位置共同影响温度。","chapterIndex":6,"sentenceIndex":1},{"start":191.334792,"end":201.646813,"text":"不能认为堆叠越高就越好；把最热的电路放在哪里，是一开始就要解决的架构问题。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":218.920312,"text":"被其他晶粒盖住的接点不容易再直接碰到，因此要预先设计测试访问。","chapterIndex":7,"sentenceIndex":0},{"start":219.100313,"end":226.146979,"text":"组装前筛选、接合后连通检查与系统测试各有任务。","chapterIndex":7,"sentenceIndex":1},{"start":226.326979,"end":234.162312,"text":"通过一次测试不是永久保证；要把覆盖率与剩余风险说清楚。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":248.894854,"text":"拉开到整体视角，高密度集成会同时提高界面质量与测试规划的重要性。","chapterIndex":8,"sentenceIndex":0},{"start":249.074854,"end":256.153229,"text":"已接合的晶粒未必能经济地拆换，所以前段筛选更有价值。","chapterIndex":8,"sentenceIndex":1},{"start":256.333229,"end":263.666292,"text":"比较方案时，要连同良品成本、热条件与返修能力一起看。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":281.44525,"text":"最后的路线是功能分层、界面设计、表面准备、对位接合、可测试性与散热验证。","chapterIndex":9,"sentenceIndex":0},{"start":281.62525,"end":295.035875,"text":"记住：3D 的重点不是把楼盖高，而是让最需要沟通的功能靠近，同时让电流、热与测试都有可靠出口。","chapterIndex":9,"sentenceIndex":1}]},"ja":{"file":"assets/packaging-tour-v33/audio/hybrid.ja.m4a","sha256":"4eb893cd8ebf2313c64bb0d8798cf6d310358cbb91f412c92a911dd107a120ae","cues":[{"start":0.35,"end":3.925063,"text":"上空から斜めへ視点を変えます。","chapterIndex":0,"sentenceIndex":0},{"start":4.105062,"end":10.893562,"text":"機能を上下に重ねると、一部のダイ間経路を短縮できます。","chapterIndex":0,"sentenceIndex":1},{"start":11.073562,"end":18.477062,"text":"回路基板を積むのではなく、管理された界面でダイを接合します。","chapterIndex":0,"sentenceIndex":2},{"start":18.657062,"end":23.580021,"text":"層を数え、それぞれの役割を確認しましょう。","chapterIndex":0,"sentenceIndex":3},{"start":30.35,"end":39.758437,"text":"上下のダイは演算、記憶、接続などを分担し、同じ製造プロセスとは限りません。","chapterIndex":1,"sentenceIndex":0},{"start":39.938437,"end":50.0365,"text":"この模型は一般的な教材で、特定の SoIC や Foveros 製品の内部配置ではありません。","chapterIndex":1,"sentenceIndex":1},{"start":50.2165,"end":54.360229,"text":"何を重ねるかはアーキテクチャで決めます。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":68.779542,"text":"界面では銅接点が電気をつなぎ、周囲の絶縁体表面も接合します。","chapterIndex":2,"sentenceIndex":0},{"start":68.959542,"end":72.882646,"text":"この組合せがハイブリッド接合です。","chapterIndex":2,"sentenceIndex":1},{"start":73.062646,"end":76.831417,"text":"大きなはんだボールの列ではありません。","chapterIndex":2,"sentenceIndex":2},{"start":77.011417,"end":84.829604,"text":"微細はんだバンプと直接接合は異なる方式で、制約も違います。","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":97.089146,"text":"ダイを離し、粒子や凹凸が界面に残る様子を考えます。","chapterIndex":3,"sentenceIndex":0},{"start":97.269146,"end":105.238854,"text":"表面処理、清浄度、平坦度、位置精度が接合品質を左右します。","chapterIndex":3,"sentenceIndex":1},{"start":105.418854,"end":115.336646,"text":"動作を遅くして原理を示しており、洗浄レシピや工程温度を提供するものではありません。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":128.525833,"text":"接合界面は短くても、データは各ダイ内の回路や配線を通ります。","chapterIndex":4,"sentenceIndex":0},{"start":128.705833,"end":138.471792,"text":"縦方向接続が解決するのは経路の一部であり、論理遅延が消えるわけではありません。","chapterIndex":4,"sentenceIndex":1},{"start":138.651792,"end":145.084146,"text":"界面を越える箇所を、信号経路全体の中で見直します。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":159.243979,"text":"高密度接点は層間通信を豊かにできますが、活用できる設計が必要です。","chapterIndex":5,"sentenceIndex":0},{"start":159.423979,"end":165.992979,"text":"接点や給電を決める前に、データと処理の分担を定めます。","chapterIndex":5,"sentenceIndex":1},{"start":166.172979,"end":175.059979,"text":"接点の多さ自体が目的ではなく、光の動きも特定の転送速度を示しません。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":183.841792,"text":"側面から熱の出口を追います。","chapterIndex":6,"sentenceIndex":0},{"start":184.021792,"end":191.838896,"text":"発熱位置、界面熱抵抗、冷却器の位置が温度に影響します。","chapterIndex":6,"sentenceIndex":1},{"start":192.018896,"end":195.440667,"text":"高く積めばよいわけではありません。","chapterIndex":6,"sentenceIndex":2},{"start":195.620667,"end":203.999313,"text":"最も熱い回路の配置は、組立後ではなく設計の初期に決める問題です。","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":219.247479,"text":"他のダイに覆われた接点へは直接触れにくくなるため、試験経路を先に設計します。","chapterIndex":7,"sentenceIndex":0},{"start":219.427479,"end":227.367708,"text":"組立前の選別、接合後の導通、システム試験は役割が異なります。","chapterIndex":7,"sentenceIndex":1},{"start":227.547708,"end":234.589479,"text":"一度の合格は永続的保証ではなく、範囲と残るリスクを示します。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":247.503562,"text":"全体を見ると、高密度化ほど界面品質と試験計画が重要です。","chapterIndex":8,"sentenceIndex":0},{"start":247.683562,"end":255.890792,"text":"接合後のダイ交換は経済的でない場合があり、事前選別の価値が高まります。","chapterIndex":8,"sentenceIndex":1},{"start":256.070792,"end":264.476917,"text":"接続密度だけでなく、良品単価、熱条件、修復性を一緒に比較します。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":281.562667,"text":"機能分割、界面設計、表面準備、位置合わせ、接合、試験性、熱検証が道筋です。","chapterIndex":9,"sentenceIndex":0},{"start":281.742667,"end":285.849063,"text":"3D の目的は高さではありません。","chapterIndex":9,"sentenceIndex":1},{"start":286.029063,"end":295.187896,"text":"通信する機能を近づけつつ、電流、熱、試験の確かな通り道を残すことです。","chapterIndex":9,"sentenceIndex":2}]},"ko":{"file":"assets/packaging-tour-v33/audio/hybrid.ko.m4a","sha256":"e2e3077c7317f4d266b2bf11e79da06c2f3d47d6661008ce3cf556b496c1d7b7","cues":[{"start":0.35,"end":3.309792,"text":"위에서 본 뒤 비스듬히 내려봅니다.","chapterIndex":0,"sentenceIndex":0},{"start":3.489792,"end":9.189667,"text":"기능을 나란히 놓는 대신 쌓으면 일부 다이 간 경로를 줄일 수 있습니다.","chapterIndex":0,"sentenceIndex":1},{"start":9.369667,"end":15.949771,"text":"회로 보드를 쌓는 방식이 아니라 정밀하게 관리한 계면에서 다이를 접합합니다.","chapterIndex":0,"sentenceIndex":2},{"start":16.129771,"end":19.675583,"text":"먼저 층수와 각 층의 역할을 확인하세요.","chapterIndex":0,"sentenceIndex":3},{"start":30.35,"end":38.911417,"text":"상하 다이는 연산, 메모리, 연결 기능을 나눌 수 있으며 같은 제조 공정을 사용할 필요는 없습니다.","chapterIndex":1,"sentenceIndex":0},{"start":39.091417,"end":46.303125,"text":"이 장면은 일반 교육 모델로 특정 SoIC 또는 Foveros 제품의 내부 배치도가 아닙니다.","chapterIndex":1,"sentenceIndex":1},{"start":46.483125,"end":51.033604,"text":"어떤 기능을 함께 쌓을지는 아키텍처가 결정합니다.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":67.127104,"text":"계면에서 구리 접점은 전기적으로 연결되고 주변 유전체 표면도 접합됩니다.","chapterIndex":2,"sentenceIndex":0},{"start":67.307104,"end":70.359813,"text":"이것이 하이브리드 본딩의 핵심입니다.","chapterIndex":2,"sentenceIndex":1},{"start":70.539812,"end":73.645396,"text":"큰 솔더볼의 줄로 이해하면 안 됩니다.","chapterIndex":2,"sentenceIndex":2},{"start":73.825396,"end":81.136333,"text":"솔더 마이크로범프와 직접 하이브리드 본딩은 서로 다른 연결 방식이며 제약도 다릅니다.","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":96.221979,"text":"다이를 분리하고 계면에 입자나 표면 요철이 남는 상황을 생각합니다.","chapterIndex":3,"sentenceIndex":0},{"start":96.401979,"end":104.101042,"text":"표면 준비, 청정도, 평탄도, 정렬 정확도가 함께 접합 품질을 좌우합니다.","chapterIndex":3,"sentenceIndex":1},{"start":104.281042,"end":111.384312,"text":"느린 동작은 원리 설명용이며 세정 방법이나 공정 온도 조건을 제시하지 않습니다.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":126.355896,"text":"접합 계면은 짧지만 데이터는 각 다이 내부 회로와 배선을 통과합니다.","chapterIndex":4,"sentenceIndex":0},{"start":126.535896,"end":132.286979,"text":"수직 연결은 경로의 일부를 해결할 뿐 논리 지연을 없애지는 않습니다.","chapterIndex":4,"sentenceIndex":1},{"start":132.466979,"end":139.226708,"text":"다이 사이를 건너는 지점을 찾고 전체 신호 경로 안에서 그 의미를 확인하세요.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":156.840396,"text":"조밀한 접점은 층간 통신을 늘릴 수 있지만 아키텍처가 이를 활용해야 합니다.","chapterIndex":5,"sentenceIndex":0},{"start":157.020396,"end":162.220042,"text":"접점과 전원을 배분하기 전에 데이터와 작업 분담을 정합니다.","chapterIndex":5,"sentenceIndex":1},{"start":162.400042,"end":165.336021,"text":"연결 수 자체가 목적은 아닙니다.","chapterIndex":5,"sentenceIndex":2},{"start":165.516021,"end":171.180167,"text":"빛의 흐름은 정보 관계이며 특정 전송 속도를 나타내지 않습니다.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":183.973375,"text":"측면에서 열이 빠져나가는 경로를 봅니다.","chapterIndex":6,"sentenceIndex":0},{"start":184.153375,"end":190.179646,"text":"발열 위치, 계면 열저항, 냉각기 위치가 온도에 영향을 줍니다.","chapterIndex":6,"sentenceIndex":1},{"start":190.359646,"end":193.407813,"text":"높이 쌓을수록 좋은 것은 아닙니다.","chapterIndex":6,"sentenceIndex":2},{"start":193.587813,"end":200.722208,"text":"가장 뜨거운 회로의 위치는 조립 후가 아니라 아키텍처 초기 단계에서 결정해야 합니다.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":218.406833,"text":"다른 다이가 덮으면 접점에 직접 접근하기 어려워지므로 시험 접근 경로를 미리 설계해야 합니다.","chapterIndex":7,"sentenceIndex":0},{"start":218.586833,"end":225.041396,"text":"조립 전 선별, 접합 후 연결 확인, 시스템 시험은 역할이 다릅니다.","chapterIndex":7,"sentenceIndex":1},{"start":225.221396,"end":231.955688,"text":"한 번의 통과가 영구 보장은 아니므로 시험 범위와 남은 위험을 명확히 해야 합니다.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":246.5975,"text":"전체로 보면 고밀도 통합일수록 계면 품질과 시험 계획이 중요합니다.","chapterIndex":8,"sentenceIndex":0},{"start":246.7775,"end":253.661229,"text":"접합된 다이를 경제적으로 교체하기 어려울 수 있어 사전 선별 가치가 커집니다.","chapterIndex":8,"sentenceIndex":1},{"start":253.841229,"end":261.502729,"text":"연결 밀도만 보지 말고 양품 단가, 열 조건, 수리 가능성을 함께 비교해야 합니다.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":280.334187,"text":"기능 분할, 계면 설계, 표면 준비, 정렬·접합, 시험 접근성, 열 검증이 전체 경로입니다.","chapterIndex":9,"sentenceIndex":0},{"start":280.514187,"end":284.851104,"text":"3D의 목표는 단순히 높이 쌓는 것이 아닙니다.","chapterIndex":9,"sentenceIndex":1},{"start":285.031104,"end":292.635646,"text":"통신하는 기능을 가까이 두면서 전류, 열, 시험의 확실한 경로를 유지하는 것입니다.","chapterIndex":9,"sentenceIndex":2}]}},"bridge":{"zh-TW":{"file":"assets/packaging-tour-v33/audio/bridge.zh-TW.m4a","sha256":"75fa16446044f5ca2b0b856d2bf56805b01b6c6639cf8b14c8cc2f7817cd2fae","cues":[{"start":0.35,"end":7.098708,"text":"從高處看兩個晶粒街區，注意交界處的一小段連接區。","chapterIndex":0,"sentenceIndex":0},{"start":7.278708,"end":16.572646,"text":"局部矽橋把精密佈線集中在需要跨越的位置，其他區域仍由封裝基板承接。","chapterIndex":0,"sentenceIndex":1},{"start":16.752646,"end":23.778104,"text":"先找出「橋在哪裡」，再思考為什麼不必讓整個底面都是橋。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":36.88175,"text":"把橋的位置高亮，就能和覆蓋較大範圍的中介層區分。","chapterIndex":1,"sentenceIndex":0},{"start":37.06175,"end":43.530875,"text":"兩者都能支援異質整合，但分配精密佈線的方式不同。","chapterIndex":1,"sentenceIndex":1},{"start":43.710875,"end":53.053375,"text":"這裡以嵌入基板的矽橋為概念，不能把所有橋接產品的結構視為完全相同。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":63.918125,"text":"沿著兩個晶粒相對的邊緣飛行。","chapterIndex":2,"sentenceIndex":0},{"start":64.098125,"end":72.689521,"text":"橋的通道要對上晶粒的接點，不能把晶粒任意旋轉就期待連線自動成立。","chapterIndex":2,"sentenceIndex":1},{"start":72.869521,"end":81.719562,"text":"晶粒邊緣的可用空間、接點配置與介面方向，都是系統平面規劃的一部分。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":97.667646,"text":"鏡頭下降到基板，橋與周圍材料必須形成可組裝的平面。","chapterIndex":3,"sentenceIndex":0},{"start":97.847646,"end":103.762854,"text":"嵌入、對位、晶粒貼合與接點形成都有公差。","chapterIndex":3,"sentenceIndex":1},{"start":103.942854,"end":114.024542,"text":"這段展示的是組裝關係，不是特定設備的操作順序；真正的流程要依合格製程文件。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":128.527875,"text":"分層示意中先追晶粒到晶粒的連線，再追向基板的供電與外部訊號。","chapterIndex":4,"sentenceIndex":0},{"start":128.707875,"end":132.183208,"text":"它們不必全部經過同一座橋。","chapterIndex":4,"sentenceIndex":1},{"start":132.363208,"end":143.973563,"text":"不同橋接技術可能加入其他垂直結構，因此不要由這張簡化分層圖推論所有產品的供電方式。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":159.586833,"text":"發光路徑表示資料能走的幾何連接，但通訊還需要兩端同意訊號與協定。","chapterIndex":5,"sentenceIndex":0},{"start":159.766833,"end":165.734146,"text":"橋是物理整合方式，不等於某個固定通訊標準。","chapterIndex":5,"sentenceIndex":1},{"start":165.914146,"end":173.651833,"text":"接下來的 UCIe 單元會把「道路怎麼造」和「車輛怎麼對話」分開說清楚。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":184.506063,"text":"橋、基板與晶粒不是同一種材料。","chapterIndex":6,"sentenceIndex":0},{"start":184.686062,"end":190.773833,"text":"溫度改變時，它們的變形差異會把應力帶到接合區。","chapterIndex":6,"sentenceIndex":1},{"start":190.953833,"end":200.989042,"text":"熱與機械分析應一起看；只看橋很小，不能直接認定它不會成為可靠度風險。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":219.712417,"text":"檢查通道是否開路或短路，再確認兩端晶粒能在指定條件下交換正確資料。","chapterIndex":7,"sentenceIndex":0},{"start":219.892417,"end":226.144396,"text":"幾何對位、電性連通與系統功能是三層不同證據。","chapterIndex":7,"sentenceIndex":1},{"start":226.324396,"end":233.534167,"text":"若發生錯誤，要能區分接點問題、訊號品質與協定設定。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":250.133417,"text":"局部橋可以把精密資源放到真正需要的地方，但晶粒配置與基板整合也因此受到約束。","chapterIndex":8,"sentenceIndex":0},{"start":250.313417,"end":257.85575,"text":"不要只比較矽面積；還要計入組裝難度、供應鏈、測試與良率。","chapterIndex":8,"sentenceIndex":1},{"start":258.03575,"end":264.332458,"text":"選擇的依據是整個產品的需求，不是單一結構的漂亮程度。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":283.624896,"text":"最後回到俯瞰：選定互通的晶粒、安排邊緣介面、配置局部橋、規劃供電散熱，再用測試證明它們能合作。","chapterIndex":9,"sentenceIndex":0},{"start":283.804896,"end":293.295062,"text":"這個技術的美感是節制：不把所有地方都變複雜，只在最重要的連接處投入精密。","chapterIndex":9,"sentenceIndex":1}]},"en":{"file":"assets/packaging-tour-v33/audio/bridge.en.m4a","sha256":"5649f66e40b0c068e7035df561b92612aa8e656daace5bff958bcdbd97dd58db","cues":[{"start":0.35,"end":5.1325,"text":"From above, find the narrow connection zone between neighboring dies.","chapterIndex":0,"sentenceIndex":0},{"start":5.3125,"end":13.756813,"text":"A local silicon bridge concentrates fine routing where a crossing is needed, while the substrate serves the surrounding area.","chapterIndex":0,"sentenceIndex":1},{"start":13.936813,"end":20.400813,"text":"Locate the bridge first, then ask why the whole package floor does not need to become one.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":34.281854,"text":"Highlight the bridge to distinguish it from a broad interposer.","chapterIndex":1,"sentenceIndex":0},{"start":34.461854,"end":40.320687,"text":"Both support heterogeneous integration, but distribute fine routing differently.","chapterIndex":1,"sentenceIndex":1},{"start":40.500687,"end":51.786687,"text":"This model explains a bridge embedded in a substrate; bridge-based products can differ in structure, so the illustration is not a universal vendor structure.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":62.636354,"text":"Fly along facing die edges.","chapterIndex":2,"sentenceIndex":0},{"start":62.816354,"end":71.386562,"text":"Bridge channels must meet the intended contacts; rotating a die arbitrarily will not make compatible wiring appear.","chapterIndex":2,"sentenceIndex":1},{"start":71.566563,"end":82.609938,"text":"Available die-edge length, contact placement and interface orientation belong in the system floorplan, before the bridge is treated as a finished connection.","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":92.337229,"text":"Descend toward the substrate.","chapterIndex":3,"sentenceIndex":0},{"start":92.517229,"end":97.900729,"text":"The bridge and surrounding material must create an assembly-compatible surface.","chapterIndex":3,"sentenceIndex":1},{"start":98.080729,"end":104.384729,"text":"Embedding, alignment, die placement and contact formation all have tolerances.","chapterIndex":3,"sentenceIndex":2},{"start":104.564729,"end":115.649146,"text":"This sequence explains assembly relationships, not a particular machine recipe; actual work follows qualified process documentation.","chapterIndex":3,"sentenceIndex":3},{"start":120.35,"end":128.934687,"text":"In the separated-layer view, trace die-to-die signals separately from power and external connections toward the substrate.","chapterIndex":4,"sentenceIndex":0},{"start":129.114688,"end":131.794979,"text":"They need not all cross the same bridge.","chapterIndex":4,"sentenceIndex":1},{"start":131.974979,"end":142.2745,"text":"Some bridge technologies add vertical structures, so this simplified view must not be used to infer every product’s power-delivery arrangement.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":153.388458,"text":"Glowing paths show geometric connectivity.","chapterIndex":5,"sentenceIndex":0},{"start":153.568458,"end":159.218271,"text":"Communication still requires compatible signaling and protocols at both ends.","chapterIndex":5,"sentenceIndex":1},{"start":159.398271,"end":165.441917,"text":"A bridge is a physical integration approach, not a single communication standard.","chapterIndex":5,"sentenceIndex":2},{"start":165.621917,"end":172.563875,"text":"The UCIe tour separates the question of how roads are built from how participants communicate over them.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":184.153188,"text":"Bridge, substrate and dies are different materials.","chapterIndex":6,"sentenceIndex":0},{"start":184.333188,"end":190.914958,"text":"Temperature changes can create mismatched deformation and concentrate stress near joints.","chapterIndex":6,"sentenceIndex":1},{"start":191.094958,"end":194.61575,"text":"Thermal and mechanical analysis belong together.","chapterIndex":6,"sentenceIndex":2},{"start":194.79575,"end":201.882146,"text":"A small bridge is not automatically free of reliability risk simply because it occupies little area.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":218.635042,"text":"Check channels for opens and shorts, then verify that the dies exchange correct data under specified conditions.","chapterIndex":7,"sentenceIndex":0},{"start":218.815042,"end":225.640583,"text":"Geometric alignment, electrical continuity and system function are different evidence layers.","chapterIndex":7,"sentenceIndex":1},{"start":225.820583,"end":233.326625,"text":"Diagnose failures by separating joint defects, signal quality and protocol configuration.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":247.790292,"text":"Local bridges focus precision where it is needed, but constrain floorplanning and substrate integration.","chapterIndex":8,"sentenceIndex":0},{"start":247.970292,"end":255.700604,"text":"Compare more than silicon area: include assembly complexity, supply chain, testing and yield.","chapterIndex":8,"sentenceIndex":1},{"start":255.880604,"end":262.871812,"text":"The right choice serves the complete product, rather than rewarding the most visually appealing structure.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":282.270562,"text":"Return overhead: choose communicating dies, arrange edge interfaces, place bridges, plan power and cooling, then prove cooperation through testing.","chapterIndex":9,"sentenceIndex":0},{"start":282.450562,"end":292.236146,"text":"The visual idea is restraint: reserve precision for critical crossings instead of making every part of the package equally complex.","chapterIndex":9,"sentenceIndex":1}]},"zh-CN":{"file":"assets/packaging-tour-v33/audio/bridge.zh-CN.m4a","sha256":"919a64e0417fd965485544c2951f6b8a6a458166bd4c393e294994935d70a2b6","cues":[{"start":0.35,"end":7.061479,"text":"从高处看两个晶粒街区，注意交界处的一小段连接区。","chapterIndex":0,"sentenceIndex":0},{"start":7.241479,"end":16.596646,"text":"局部硅桥把精密布线集中在需要跨越的位置，其他区域仍由封装基板承接。","chapterIndex":0,"sentenceIndex":1},{"start":16.776646,"end":23.920417,"text":"先找出桥在哪里，再思考为什么不必让整个底面都是桥。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":37.238937,"text":"把桥的位置高亮，就能和覆盖较大范围的中介层区分。","chapterIndex":1,"sentenceIndex":0},{"start":37.418937,"end":44.285896,"text":"两者都能支持异构集成，但分配精密布线的方式不同。","chapterIndex":1,"sentenceIndex":1},{"start":44.465896,"end":53.977208,"text":"这里以嵌入基板的硅桥为概念，不能把所有桥接产品的结构视为完全相同。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":64.099167,"text":"沿着两个晶粒相对的边缘飞行。","chapterIndex":2,"sentenceIndex":0},{"start":64.279167,"end":73.197771,"text":"桥的通道要对上晶粒的接点，不能把晶粒任意旋转就期待连线自动成立。","chapterIndex":2,"sentenceIndex":1},{"start":73.377771,"end":83.000583,"text":"晶粒边缘的可用空间、接点配置与接口方向，都是系统平面规划的一部分。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":97.747833,"text":"镜头下降到基板，桥与周围材料必须形成可组装的平面。","chapterIndex":3,"sentenceIndex":0},{"start":97.927833,"end":104.106521,"text":"嵌入、对位、晶粒贴合与接点形成都有公差。","chapterIndex":3,"sentenceIndex":1},{"start":104.286521,"end":114.402271,"text":"这段展示的是组装关系，不是特定设备的操作顺序；真正的流程要依合格工艺文件。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":128.843667,"text":"分層示意中先追晶粒到晶粒的连线，再追向基板的供电与外部信号。","chapterIndex":4,"sentenceIndex":0},{"start":129.023667,"end":132.597917,"text":"它们不必全部经过同一座桥。","chapterIndex":4,"sentenceIndex":1},{"start":132.777917,"end":144.647354,"text":"不同桥接技术可能加入其他垂直结构，因此不要由这张简化分层图推论所有产品的供电方式。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":159.532042,"text":"发光路径表示数据能走的几何连接，但通信还需要两端同意信号与协议。","chapterIndex":5,"sentenceIndex":0},{"start":159.712042,"end":165.905292,"text":"桥是物理集成方式，不等于某个固定通信标准。","chapterIndex":5,"sentenceIndex":1},{"start":166.085292,"end":173.722854,"text":"接下来的 UCIe 单元会把道路怎么造和车辆怎么对话分开说清楚。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":184.677896,"text":"桥、基板与晶粒不是同一种材料。","chapterIndex":6,"sentenceIndex":0},{"start":184.857896,"end":191.361083,"text":"温度改变时，它们的变形差异会把应力带到接合区。","chapterIndex":6,"sentenceIndex":1},{"start":191.541083,"end":201.701687,"text":"热与机械分析应一起看；只看桥很小，不能直接认定它不会成为可靠性风险。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":220.366333,"text":"检查通道是否开路或短路，再确认两端晶粒能在指定条件下交换正确数据。","chapterIndex":7,"sentenceIndex":0},{"start":220.546333,"end":226.799,"text":"几何对位、电性连通与系统功能是三层不同证据。","chapterIndex":7,"sentenceIndex":1},{"start":226.979,"end":234.51575,"text":"若发生错误，要能区分接点问题、信号质量与协议设置。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":250.300167,"text":"局部桥可以把精密资源放到真正需要的地方，但晶粒配置与基板集成也因此受到约束。","chapterIndex":8,"sentenceIndex":0},{"start":250.480167,"end":257.783667,"text":"不要只比较硅面积；还要计入组装难度、供应链、测试与良率。","chapterIndex":8,"sentenceIndex":1},{"start":257.963667,"end":264.3985,"text":"选择的依据是整个产品的需求，不是单一结构的漂亮程度。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":284.658813,"text":"最后回到俯瞰：选定互通的晶粒、安排边缘接口、配置局部桥、规划供电散热，再用测试证明它们能合作。","chapterIndex":9,"sentenceIndex":0},{"start":284.838813,"end":294.546438,"text":"这个技术的美感是节制：不把所有地方都变复杂，只在最重要的连接处投入精密。","chapterIndex":9,"sentenceIndex":1}]},"ja":{"file":"assets/packaging-tour-v33/audio/bridge.ja.m4a","sha256":"e88675cac846137a90ff5ec80124877bfb8db7679f13945a6e886faabe54367f","cues":[{"start":0.35,"end":6.966479,"text":"上空から隣り合うダイの境界にある接続部分を探します。","chapterIndex":0,"sentenceIndex":0},{"start":7.146479,"end":17.068042,"text":"局所シリコンブリッジは必要な場所に微細配線を集中させ、周囲は基板が支えます。","chapterIndex":0,"sentenceIndex":1},{"start":17.248042,"end":24.750688,"text":"橋の場所を見つけ、底面全体を橋にしなくてよい理由を考えます。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":37.622563,"text":"橋だけを強調すると、広い面積を覆う中間層との違いが分かります。","chapterIndex":1,"sentenceIndex":0},{"start":37.802563,"end":44.983125,"text":"どちらも異種集積を支えますが、微細配線の配置方法が異なります。","chapterIndex":1,"sentenceIndex":1},{"start":45.163125,"end":54.229792,"text":"この模型は基板埋込み型の概念で、全製品に共通する構造図ではありません。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":63.808917,"text":"向かい合うダイの縁に沿って飛びます。","chapterIndex":2,"sentenceIndex":0},{"start":63.988917,"end":74.404625,"text":"橋の配線は所定の接点に合う必要があり、自由に回転させても接続は成立しません。","chapterIndex":2,"sentenceIndex":1},{"start":74.584625,"end":83.170625,"text":"縁の長さ、接点配置、インターフェースの向きは、システム配置計画の一部です。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":91.96575,"text":"基板へ降ります。","chapterIndex":3,"sentenceIndex":0},{"start":92.14575,"end":104.653604,"text":"橋と周囲の材料は組立可能な面を作る必要があり、埋込み、位置合わせ、搭載、接点形成には公差があります。","chapterIndex":3,"sentenceIndex":1},{"start":104.833604,"end":110.836104,"text":"ここでは関係を示し、特定装置の手順ではありません。","chapterIndex":3,"sentenceIndex":2},{"start":111.016104,"end":114.899479,"text":"実作業は認定工程書に従います。","chapterIndex":3,"sentenceIndex":3},{"start":120.35,"end":128.213146,"text":"分けた層からダイ間信号と、基板へ向かう電源・外部接続を分けて追います。","chapterIndex":4,"sentenceIndex":0},{"start":128.393146,"end":132.712604,"text":"すべてが同じ橋を渡る必要はありません。","chapterIndex":4,"sentenceIndex":1},{"start":132.892604,"end":144.6205,"text":"縦方向構造を加える方式もあるため、この簡略な分層図から全製品の給電方式を推測してはいけません。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":153.965333,"text":"光る経路は幾何的な接続です。","chapterIndex":5,"sentenceIndex":0},{"start":154.145333,"end":160.390562,"text":"通信には両端の信号とプロトコルの適合が必要です。","chapterIndex":5,"sentenceIndex":1},{"start":160.570562,"end":168.238063,"text":"橋は物理的な集積方法で、特定の通信規格そのものではありません。","chapterIndex":5,"sentenceIndex":2},{"start":168.418062,"end":175.281333,"text":"UCIe 編では道路の作り方と通信ルールを分けて説明します。","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":184.46225,"text":"橋、基板、ダイは異なる材料です。","chapterIndex":6,"sentenceIndex":0},{"start":184.64225,"end":190.959354,"text":"温度変化による変形の差が接合部に応力を生みます。","chapterIndex":6,"sentenceIndex":1},{"start":191.139354,"end":194.841729,"text":"熱と機械を一緒に解析します。","chapterIndex":6,"sentenceIndex":2},{"start":195.021729,"end":203.820188,"text":"面積が小さいという理由だけで、橋の信頼性リスクがないとは判断できません。","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":219.130687,"text":"断線と短絡を調べ、指定条件で正しいデータを交換できるか確認します。","chapterIndex":7,"sentenceIndex":0},{"start":219.310688,"end":227.119458,"text":"幾何的な整列、電気的導通、システム機能は別々の証拠です。","chapterIndex":7,"sentenceIndex":1},{"start":227.299458,"end":234.517521,"text":"故障時は接点、信号品質、プロトコル設定を切り分けます。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":250.728521,"text":"局所ブリッジは精密さを必要箇所へ集中できますが、配置と基板統合に制約も生みます。","chapterIndex":8,"sentenceIndex":0},{"start":250.908521,"end":259.294104,"text":"シリコン面積だけでなく、組立、供給網、試験、歩留まりを比べます。","chapterIndex":8,"sentenceIndex":1},{"start":259.474104,"end":265.399688,"text":"選択基準は見栄えではなく製品全体の要求です。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":281.904021,"text":"通信するダイ、縁のインターフェース、橋、電源と冷却を配置し、試験で協調動作を証明します。","chapterIndex":9,"sentenceIndex":0},{"start":282.084021,"end":288.889875,"text":"全体を複雑にせず、重要な接続に精密さを注ぐ。","chapterIndex":9,"sentenceIndex":1},{"start":289.069875,"end":293.327938,"text":"その節度が、この技術の美しさです。","chapterIndex":9,"sentenceIndex":2}]},"ko":{"file":"assets/packaging-tour-v33/audio/bridge.ko.m4a","sha256":"cd48167db9c22aecd5b7173fae892b809770f8ba3a80fe6fe7c0ed05e2bff377","cues":[{"start":0.35,"end":4.969458,"text":"위에서 이웃한 다이 사이의 좁은 연결 구역을 찾습니다.","chapterIndex":0,"sentenceIndex":0},{"start":5.149458,"end":12.731917,"text":"로컬 실리콘 브리지는 건너야 하는 곳에 미세 배선을 집중하고 주변은 기판이 담당합니다.","chapterIndex":0,"sentenceIndex":1},{"start":12.911917,"end":20.336917,"text":"먼저 다리의 위치를 찾은 뒤 패키지 바닥 전체가 다리일 필요가 없는 이유를 생각하세요.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":35.131833,"text":"브리지만 강조하면 넓은 인터포저와 구분할 수 있습니다.","chapterIndex":1,"sentenceIndex":0},{"start":35.311833,"end":40.905812,"text":"두 방식 모두 이종 집적을 지원하지만 미세 배선의 배치가 다릅니다.","chapterIndex":1,"sentenceIndex":1},{"start":41.085813,"end":47.975125,"text":"이 모델은 기판 내장형 브리지의 개념이며 모든 제품에 공통인 구조도는 아닙니다.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":63.639479,"text":"마주 보는 다이 가장자리를 따라갑니다.","chapterIndex":2,"sentenceIndex":0},{"start":63.819479,"end":71.782438,"text":"브리지 채널은 정해진 접점과 맞아야 하므로 다이를 임의로 돌려도 연결이 자동으로 생기지 않습니다.","chapterIndex":2,"sentenceIndex":1},{"start":71.962437,"end":79.748479,"text":"가장자리 길이, 접점 배치, 인터페이스 방향을 시스템 배치 계획에 포함해야 합니다.","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":92.38425,"text":"기판 쪽으로 내려갑니다.","chapterIndex":3,"sentenceIndex":0},{"start":92.56425,"end":97.338417,"text":"브리지와 주변 재료는 조립 가능한 표면을 형성해야 합니다.","chapterIndex":3,"sentenceIndex":1},{"start":97.518417,"end":103.538917,"text":"내장, 정렬, 다이 배치, 접점 형성에는 공차가 있습니다.","chapterIndex":3,"sentenceIndex":2},{"start":103.718917,"end":112.006313,"text":"이 장면은 조립 관계를 설명하며 특정 장비의 작업 순서는 검증된 공정 문서에 따라야 합니다.","chapterIndex":3,"sentenceIndex":3},{"start":120.35,"end":127.606208,"text":"분리한 층에서 다이 간 신호와 기판으로 향하는 전원·외부 연결을 따로 추적합니다.","chapterIndex":4,"sentenceIndex":0},{"start":127.786208,"end":131.237146,"text":"모두 같은 브리지를 지날 필요는 없습니다.","chapterIndex":4,"sentenceIndex":1},{"start":131.417146,"end":140.953521,"text":"수직 구조를 추가하는 기술도 있으므로 이 단순화한 층별 보기로 모든 제품의 전력 공급 방식을 추론하면 안 됩니다.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":154.260312,"text":"빛나는 경로는 기하학적 연결을 나타냅니다.","chapterIndex":5,"sentenceIndex":0},{"start":154.440313,"end":159.414792,"text":"통신하려면 양쪽 신호와 프로토콜도 호환되어야 합니다.","chapterIndex":5,"sentenceIndex":1},{"start":159.594792,"end":164.761646,"text":"브리지는 물리적 통합 방식이지 하나의 통신 표준이 아닙니다.","chapterIndex":5,"sentenceIndex":2},{"start":164.941646,"end":171.6735,"text":"UCIe 안내에서는 도로를 만드는 방식과 그 위에서 통신하는 규칙을 구분합니다.","chapterIndex":5,"sentenceIndex":3},{"start":180.35,"end":184.585792,"text":"브리지, 기판, 다이는 서로 다른 재료입니다.","chapterIndex":6,"sentenceIndex":0},{"start":184.765792,"end":190.848021,"text":"온도 변화에 따른 변형 차이는 접합부에 응력을 집중시킬 수 있습니다.","chapterIndex":6,"sentenceIndex":1},{"start":191.028021,"end":193.966542,"text":"열과 기계 해석을 함께 해야 합니다.","chapterIndex":6,"sentenceIndex":2},{"start":194.146542,"end":199.728646,"text":"면적이 작다는 이유만으로 신뢰성 위험이 없다고 볼 수는 없습니다.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":218.755542,"text":"채널의 단선과 단락을 검사한 뒤 정해진 조건에서 두 다이가 올바른 데이터를 교환하는지 확인합니다.","chapterIndex":7,"sentenceIndex":0},{"start":218.935542,"end":224.635687,"text":"정렬, 전기적 연결, 시스템 기능은 서로 다른 증거입니다.","chapterIndex":7,"sentenceIndex":1},{"start":224.815687,"end":231.930354,"text":"오류가 나면 접점 결함, 신호 품질, 프로토콜 설정을 분리해 진단합니다.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":247.974229,"text":"로컬 브리지는 필요한 곳에 정밀성을 집중하지만 다이 배치와 기판 통합에 제약을 줍니다.","chapterIndex":8,"sentenceIndex":0},{"start":248.154229,"end":255.312375,"text":"실리콘 면적뿐 아니라 조립 난도, 공급망, 시험, 수율도 비교해야 합니다.","chapterIndex":8,"sentenceIndex":1},{"start":255.492375,"end":260.374292,"text":"선택 기준은 구조의 외관이 아니라 제품 전체의 요구입니다.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":279.576396,"text":"통신할 다이와 가장자리 인터페이스, 브리지, 전원·냉각을 배치하고 시험으로 협력을 증명합니다.","chapterIndex":9,"sentenceIndex":0},{"start":279.756396,"end":288.313042,"text":"모든 부분을 복잡하게 만들지 않고 중요한 연결에 정밀성을 집중하는 절제가 이 기술의 아름다움입니다.","chapterIndex":9,"sentenceIndex":1}]}},"chiplet":{"zh-TW":{"file":"assets/packaging-tour-v33/audio/chiplet.zh-TW.m4a","sha256":"a2de5bad545620a6968f36a3de43620dfc772630ba14c87c6f2787d88c6999da","cues":[{"start":0.35,"end":6.251917,"text":"俯瞰運算、記憶體控制與輸入輸出等功能街區。","chapterIndex":0,"sentenceIndex":0},{"start":6.431917,"end":15.350062,"text":"Chiplet 是把系統分成可整合的晶粒，不是把任意晶片放在一起就會合作。","chapterIndex":0,"sentenceIndex":1},{"start":15.530062,"end":22.385813,"text":"先畫出誰需要交換哪些資料，再決定哪些功能值得拆開。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":34.730104,"text":"不同功能未必需要相同的製程條件。","chapterIndex":1,"sentenceIndex":0},{"start":34.910104,"end":44.063812,"text":"拆分可以讓各晶粒採用適合的技術，也帶來介面、供電與封裝整合成本。","chapterIndex":1,"sentenceIndex":1},{"start":44.243813,"end":55.145542,"text":"這是一種設計選項，不是任何產品都必須改成 Chiplet；小而單純的系統可能有別的最佳解。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":71.358438,"text":"現在看晶粒邊界：UCIe 針對封裝內晶粒間互連定義介面規則，涵蓋實體層與相關通訊機制。","chapterIndex":2,"sentenceIndex":0},{"start":71.538438,"end":75.854417,"text":"它不是某種矽橋，也不是冷卻技術。","chapterIndex":2,"sentenceIndex":1},{"start":76.034417,"end":82.415688,"text":"把「封裝結構」和「互連標準」分開，才能正確組合方案。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":100.844208,"text":"把晶粒放進規劃位置之前，先確認介面位置、電源需求、時脈策略與封裝能力。","chapterIndex":3,"sentenceIndex":0},{"start":101.024208,"end":107.987479,"text":"標準化能減少協調成本，卻不會自動解決所有相容問題。","chapterIndex":3,"sentenceIndex":1},{"start":108.167479,"end":115.084812,"text":"這裡的拼合動作代表經過設計的整合，不是隨插即用的保證。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":126.614854,"text":"在剖面看金屬與接點，在上方看訊息如何交換。","chapterIndex":4,"sentenceIndex":0},{"start":126.794854,"end":135.691917,"text":"實體連接回答訊號能否可靠傳送，協定則規範資料如何被理解與管理。","chapterIndex":4,"sentenceIndex":1},{"start":135.871917,"end":144.341229,"text":"相同連線形狀不代表相同語意；系統必須核對雙方實際支援的功能。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":158.42275,"text":"跟著資料從一個功能區移到另一個，留意每次跨界都需要介面工作。","chapterIndex":5,"sentenceIndex":0},{"start":158.60275,"end":163.68625,"text":"拆分得太細，可能增加溝通與同步負擔。","chapterIndex":5,"sentenceIndex":1},{"start":163.86625,"end":172.601,"text":"路線圖要標出資料量、延遲與能量預算，不能只把每個區塊的算力加總。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":188.357229,"text":"把功能地圖切換成概念熱圖，觀察高負載晶粒與旁邊元件的距離。","chapterIndex":6,"sentenceIndex":0},{"start":188.537229,"end":194.737792,"text":"系統效能可能受最熱、最缺電或最忙的連線限制。","chapterIndex":6,"sentenceIndex":1},{"start":194.917792,"end":202.807333,"text":"設計應協調功率管理與散熱，不能把每個晶粒當成互不影響的孤島。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":218.754229,"text":"檢查站不只問晶粒各自能否工作，也問連在一起是否符合共同條件。","chapterIndex":7,"sentenceIndex":0},{"start":218.934229,"end":227.181583,"text":"驗證連線啟動、錯誤處理與目標工作負載，並保留版本與設定紀錄。","chapterIndex":7,"sentenceIndex":1},{"start":227.361583,"end":234.140688,"text":"貼上 UCIe 名稱不等於完成所有產品層級的相容性驗證。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":249.233646,"text":"重用晶粒可以讓產品組合更靈活，但也增加供應商、版本與驗證工作的協調。","chapterIndex":8,"sentenceIndex":0},{"start":249.413646,"end":257.213375,"text":"比較單晶片與 Chiplet 時，要看開發時間、良品成本與長期維護。","chapterIndex":8,"sentenceIndex":1},{"start":257.393375,"end":264.184125,"text":"沒有一種拆分方式適合所有需求，路線圖應保留取捨依據。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":278.78375,"text":"最後俯瞰功能分割、介面選擇、實體封裝、供電散熱與系統驗證。","chapterIndex":9,"sentenceIndex":0},{"start":278.96375,"end":287.435375,"text":"你應能分清三件事：晶粒負責什麼、封裝怎麼連、協定怎麼合作。","chapterIndex":9,"sentenceIndex":1},{"start":287.615375,"end":294.810313,"text":"Chiplet 的美感是有秩序的分工，而完整證據讓分工真正成立。","chapterIndex":9,"sentenceIndex":2}]},"en":{"file":"assets/packaging-tour-v33/audio/chiplet.en.m4a","sha256":"0e72269e3df36dc612a62eeb0a6176717bc75a77095d75c17b7b47c16c24d651","cues":[{"start":0.35,"end":5.461979,"text":"Look over districts for compute, memory control and input/output.","chapterIndex":0,"sentenceIndex":0},{"start":5.641979,"end":14.148979,"text":"Chiplets partition a system into integrable dies; placing arbitrary chips together does not make them cooperate.","chapterIndex":0,"sentenceIndex":1},{"start":14.328979,"end":21.496063,"text":"First map which functions exchange which data, then decide where splitting the system is worthwhile.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":34.763937,"text":"Different functions need not use the same process technology.","chapterIndex":1,"sentenceIndex":0},{"start":34.943937,"end":42.496375,"text":"Partitioning can match technology to purpose, but adds interface, power and packaging costs.","chapterIndex":1,"sentenceIndex":1},{"start":42.676375,"end":52.284875,"text":"Chiplets are a design option, not a requirement for every product; a smaller, simpler system may favor another architecture.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":70.971875,"text":"At the die boundary, UCIe supplies standardized rules for on-package die-to-die connectivity, including physical and communication mechanisms.","chapterIndex":2,"sentenceIndex":0},{"start":71.151875,"end":74.734875,"text":"It is not a silicon bridge or a cooling technology.","chapterIndex":2,"sentenceIndex":1},{"start":74.914875,"end":81.307729,"text":"Separate the package structure from the interconnect standard before combining them into a system.","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":99.827104,"text":"Before placing dies, align interface locations, power requirements, clocking strategy and package capability.","chapterIndex":3,"sentenceIndex":0},{"start":100.007104,"end":107.767938,"text":"Standardization can reduce coordination work, but cannot automatically solve every compatibility issue.","chapterIndex":3,"sentenceIndex":1},{"start":107.947937,"end":116.292396,"text":"The assembly animation represents designed integration, not a guarantee that any two components are plug-and-play.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":125.678854,"text":"The section reveals metal and contacts; the upper view shows messages.","chapterIndex":4,"sentenceIndex":0},{"start":125.858854,"end":134.029208,"text":"Physical connectivity addresses reliable signaling, while protocols organize the meaning and management of data.","chapterIndex":4,"sentenceIndex":1},{"start":134.209208,"end":138.984958,"text":"Similar-looking connections need not carry identical semantics.","chapterIndex":4,"sentenceIndex":2},{"start":139.164958,"end":143.3485,"text":"Verify what functions both endpoints actually support.","chapterIndex":4,"sentenceIndex":3},{"start":150.35,"end":153.519583,"text":"Follow data between functional districts.","chapterIndex":5,"sentenceIndex":0},{"start":153.699583,"end":162.879875,"text":"Every boundary crossing requires interface work; excessive partitioning can add communication and synchronization overhead.","chapterIndex":5,"sentenceIndex":1},{"start":163.059875,"end":172.727812,"text":"The roadmap must budget data volume, latency and energy instead of merely adding up the computing capability of individual blocks.","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":183.859667,"text":"Switch the function map to an illustrative heat map.","chapterIndex":6,"sentenceIndex":0},{"start":184.039667,"end":187.808333,"text":"Observe the distance between a busy die and its neighbors.","chapterIndex":6,"sentenceIndex":1},{"start":187.988333,"end":194.852688,"text":"System performance may be limited by the hottest die, weakest power path or busiest link.","chapterIndex":6,"sentenceIndex":2},{"start":195.032688,"end":201.102667,"text":"Coordinate power management and cooling rather than treating dies as isolated islands.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":217.241938,"text":"Test not only whether dies work separately, but whether the assembled system meets shared conditions.","chapterIndex":7,"sentenceIndex":0},{"start":217.421938,"end":225.001354,"text":"Exercise link startup, error handling and target workloads; record versions and configurations.","chapterIndex":7,"sentenceIndex":1},{"start":225.181354,"end":232.126042,"text":"A UCIe label does not replace complete product-level integration and interoperability validation.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":249.386104,"text":"Reusing chiplets can make product families more flexible, while adding supplier, version and validation coordination.","chapterIndex":8,"sentenceIndex":0},{"start":249.566104,"end":257.629875,"text":"Compare monolithic and chiplet designs using development time, cost per good unit and long-term maintenance.","chapterIndex":8,"sentenceIndex":1},{"start":257.809875,"end":264.260583,"text":"No partition fits every need; preserve the reasoning behind each architectural trade-off.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":278.767688,"text":"Survey partitioning, interface selection, physical packaging, power, cooling and system validation.","chapterIndex":9,"sentenceIndex":0},{"start":278.947688,"end":287.500125,"text":"Distinguish three questions: what each die does, how the package connects it and how protocols coordinate behavior.","chapterIndex":9,"sentenceIndex":1},{"start":287.680125,"end":295.154063,"text":"Chiplet elegance comes from orderly specialization, supported by evidence that the whole system works.","chapterIndex":9,"sentenceIndex":2}]},"zh-CN":{"file":"assets/packaging-tour-v33/audio/chiplet.zh-CN.m4a","sha256":"1c970edd94f29151738104566199138b2d98463d8390cb0805d30199f91aa820","cues":[{"start":0.35,"end":6.130792,"text":"俯瞰计算、内存控制与输入输出等功能街区。","chapterIndex":0,"sentenceIndex":0},{"start":6.310792,"end":15.2445,"text":"Chiplet 是把系统分成可集成的晶粒，不是把任意芯片放在一起就会合作。","chapterIndex":0,"sentenceIndex":1},{"start":15.4245,"end":22.728687,"text":"先画出谁需要交换哪些数据，再决定哪些功能值得拆开。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":34.488875,"text":"不同功能未必需要相同的工艺条件。","chapterIndex":1,"sentenceIndex":0},{"start":34.668875,"end":43.770437,"text":"拆分可以让各晶粒采用适合的技术，也带来接口、供电与封装集成成本。","chapterIndex":1,"sentenceIndex":1},{"start":43.950437,"end":55.211042,"text":"这是一种设计选项，不是任何产品都必须改成 Chiplet；小而单纯的系统可能有别的最佳解。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":71.795417,"text":"现在看晶粒边界：UCIe 针对封装内晶粒间互连定义接口规则，涵盖物理层与相关通信机制。","chapterIndex":2,"sentenceIndex":0},{"start":71.975417,"end":76.61275,"text":"它不是某种硅桥，也不是冷却技术。","chapterIndex":2,"sentenceIndex":1},{"start":76.79275,"end":83.461146,"text":"把封装结构和互连标准分开，才能正确组合方案。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":100.234646,"text":"把晶粒放进规划位置之前，先确认接口位置、电源需求、时钟策略与封装能力。","chapterIndex":3,"sentenceIndex":0},{"start":100.414646,"end":107.27075,"text":"标准化能减少协调成本，却不会自动解决所有兼容问题。","chapterIndex":3,"sentenceIndex":1},{"start":107.45075,"end":114.225042,"text":"这里的拼合动作代表经过设计的集成，不是即插即用的保证。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":126.911146,"text":"在剖面看金属与接点，在上方看消息如何交换。","chapterIndex":4,"sentenceIndex":0},{"start":127.091146,"end":136.199917,"text":"实体连接回答信号能否可靠传送，协议则规范数据如何被理解与管理。","chapterIndex":4,"sentenceIndex":1},{"start":136.379917,"end":145.292,"text":"相同连线形状不代表相同语义；系统必须核对双方实际支持的功能。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":158.294417,"text":"跟着数据从一个功能区移到另一个，留意每次跨界都需要接口工作。","chapterIndex":5,"sentenceIndex":0},{"start":158.474417,"end":163.788437,"text":"拆分得太细，可能增加沟通与同步负担。","chapterIndex":5,"sentenceIndex":1},{"start":163.968437,"end":173.419417,"text":"路线图要标出数据量、延迟与能量预算，不能只把每个区块的算力加总。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":188.865167,"text":"把功能地图切换成概念热图，观察高负载晶粒与旁边元件的距离。","chapterIndex":6,"sentenceIndex":0},{"start":189.045167,"end":195.568979,"text":"系统性能可能受最热、最缺电或最忙的连线限制。","chapterIndex":6,"sentenceIndex":1},{"start":195.748979,"end":204.145688,"text":"设计应协调功率管理与散热，不能把每个晶粒当成互不影响的孤岛。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":219.234271,"text":"检查站不只问晶粒各自能否工作，也问连在一起是否符合共同条件。","chapterIndex":7,"sentenceIndex":0},{"start":219.414271,"end":228.112604,"text":"验证连线启动、错误处理与目标工作负载，并保留版本与设置记录。","chapterIndex":7,"sentenceIndex":1},{"start":228.292604,"end":235.245396,"text":"贴上 UCIe 名称不等于完成所有产品层级的兼容性验证。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":249.492146,"text":"复用晶粒可以让产品组合更灵活，但也增加供应商、版本与验证工作的协调。","chapterIndex":8,"sentenceIndex":0},{"start":249.672146,"end":257.625083,"text":"比较单芯片与 Chiplet 时，要看开发时间、良品成本与长期维护。","chapterIndex":8,"sentenceIndex":1},{"start":257.805083,"end":264.769,"text":"没有一种拆分方式适合所有需求，路线图应保留取舍依据。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":279.419271,"text":"最后俯瞰功能分割、接口选择、实体封装、供电散热与系统验证。","chapterIndex":9,"sentenceIndex":0},{"start":279.599271,"end":287.966854,"text":"你应能分清三件事：晶粒负责什么、封装怎么连、协议怎么合作。","chapterIndex":9,"sentenceIndex":1},{"start":288.146854,"end":295.204,"text":"Chiplet 的美感是有秩序的分工，而完整证据让分工真正成立。","chapterIndex":9,"sentenceIndex":2}]},"ja":{"file":"assets/packaging-tour-v33/audio/chiplet.ja.m4a","sha256":"9acc386b423cf5dbc2c640f740afe66b0f4e98ce890d1d744126532cbfd8eda8","cues":[{"start":0.35,"end":6.259042,"text":"演算、メモリー制御、入出力の街区を見渡します。","chapterIndex":0,"sentenceIndex":0},{"start":6.439042,"end":15.480771,"text":"チップレットは統合可能なダイへの分割であり、任意のチップを並べることではありません。","chapterIndex":0,"sentenceIndex":1},{"start":15.660771,"end":22.579062,"text":"まず機能間のデータ交換を描き、どこを分ける価値があるか決めます。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":36.838583,"text":"すべての機能が同じ製造技術を必要とするわけではありません。","chapterIndex":1,"sentenceIndex":0},{"start":37.018583,"end":44.593375,"text":"分割で技術を選べますが、接続、電源、パッケージのコストも増えます。","chapterIndex":1,"sentenceIndex":1},{"start":44.773375,"end":53.717104,"text":"チップレットは選択肢であり、単純な小規模システムでは別の構成が適する場合があります。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":72.078583,"text":"ダイの境界で、UCIe はパッケージ内のダイ間接続に物理層や通信機構の共通規則を与えます。","chapterIndex":2,"sentenceIndex":0},{"start":72.258583,"end":76.788021,"text":"シリコンブリッジや冷却技術ではありません。","chapterIndex":2,"sentenceIndex":1},{"start":76.968021,"end":84.716375,"text":"パッケージ構造と相互接続規格を分けて理解してから組み合わせます。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":98.491833,"text":"搭載前にインターフェース位置、電源、クロック、パッケージ技術の能力を揃えます。","chapterIndex":3,"sentenceIndex":0},{"start":98.671833,"end":106.313938,"text":"標準化は調整を減らせても、全ての相性問題を自動解決しません。","chapterIndex":3,"sentenceIndex":1},{"start":106.493938,"end":115.7475,"text":"模型の組合せは設計済みの統合であり、任意部品の交換可能性を保証しません。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":126.26225,"text":"断面では金属と接点、上ではメッセージを見ます。","chapterIndex":4,"sentenceIndex":0},{"start":126.44225,"end":135.915188,"text":"物理接続は信号を確実に運べるかを扱い、プロトコルは意味と管理を定めます。","chapterIndex":4,"sentenceIndex":1},{"start":136.095188,"end":144.784812,"text":"同じ形でも意味は同じとは限らず、両端が対応する機能を確認します。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":157.638625,"text":"機能間のデータを追うと、境界ごとにインターフェース処理が必要です。","chapterIndex":5,"sentenceIndex":0},{"start":157.818625,"end":163.364979,"text":"細かく分けすぎると通信と同期の負担が増えます。","chapterIndex":5,"sentenceIndex":1},{"start":163.544979,"end":172.539417,"text":"各ブロックの計算能力を足すだけでなく、データ量、遅延、エネルギーを配分します。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":184.886375,"text":"機能地図を概念的な熱地図へ変えます。","chapterIndex":6,"sentenceIndex":0},{"start":185.066375,"end":189.194458,"text":"高負荷ダイと周囲の距離を見てください。","chapterIndex":6,"sentenceIndex":1},{"start":189.374458,"end":197.047854,"text":"最も熱いダイ、弱い給電、混雑したリンクが性能を制限します。","chapterIndex":6,"sentenceIndex":2},{"start":197.227854,"end":204.767188,"text":"独立した島と考えず、電力管理と冷却を協調させます。","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":218.3705,"text":"個別のダイだけでなく、接続したシステムが共通条件を満たすか試験します。","chapterIndex":7,"sentenceIndex":0},{"start":218.5505,"end":225.978938,"text":"リンク起動、エラー処理、対象負荷を確認し、版と設定を記録します。","chapterIndex":7,"sentenceIndex":1},{"start":226.158938,"end":233.960583,"text":"UCIe の名称だけでは製品全体の相互運用検証を代替できません。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":250.480479,"text":"再利用は製品展開を柔軟にしますが、供給元、版、検証の調整も増えます。","chapterIndex":8,"sentenceIndex":0},{"start":250.660479,"end":259.105563,"text":"一枚のチップと比較するときは開発期間、良品単価、長期保守を見ます。","chapterIndex":8,"sentenceIndex":1},{"start":259.285563,"end":265.255875,"text":"万能な分割はなく、選択理由を地図に残します。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":280.311917,"text":"機能分割、接続規格、物理的なパッケージ、電源、冷却、システム検証を見渡します。","chapterIndex":9,"sentenceIndex":0},{"start":280.491917,"end":288.450208,"text":"ダイの役割、パッケージのつなぎ方、通信の協調という三点を区別します。","chapterIndex":9,"sentenceIndex":1},{"start":288.630208,"end":295.208771,"text":"秩序ある分担が美しさを生み、検証がそれを成立させます。","chapterIndex":9,"sentenceIndex":2}]},"ko":{"file":"assets/packaging-tour-v33/audio/chiplet.ko.m4a","sha256":"d4c56482b1a77451ee9eda15eb2e1d7a55e8919021724788be4ace0ae574d506","cues":[{"start":0.35,"end":4.983521,"text":"연산, 메모리 제어, 입출력 구역을 내려다봅니다.","chapterIndex":0,"sentenceIndex":0},{"start":5.163521,"end":12.396771,"text":"칩렛은 통합 가능한 다이로 시스템을 나누는 방식이지 임의의 칩을 모으는 것이 아닙니다.","chapterIndex":0,"sentenceIndex":1},{"start":12.576771,"end":18.857,"text":"먼저 어떤 기능이 어떤 데이터를 교환하는지 그린 뒤 분할할 지점을 정합니다.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":34.944167,"text":"모든 기능이 같은 공정 기술을 필요로 하지는 않습니다.","chapterIndex":1,"sentenceIndex":0},{"start":35.124167,"end":43.564625,"text":"분할하면 기능에 맞는 기술을 선택할 수 있지만 인터페이스, 전원, 패키징 비용이 추가됩니다.","chapterIndex":1,"sentenceIndex":1},{"start":43.744625,"end":51.234104,"text":"칩렛은 설계 선택지이며 작고 단순한 시스템에는 다른 구성이 더 적합할 수 있습니다.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":69.217125,"text":"다이 경계에서 UCIe는 패키지 내부 다이 간 연결의 물리 계층과 통신 방식에 공통 규칙을 제공합니다.","chapterIndex":2,"sentenceIndex":0},{"start":69.397125,"end":72.746125,"text":"실리콘 브리지나 냉각 기술이 아닙니다.","chapterIndex":2,"sentenceIndex":1},{"start":72.926125,"end":78.417521,"text":"패키지 구조와 연결 표준을 구분한 뒤 시스템으로 조합해야 합니다.","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":98.3105,"text":"다이를 놓기 전에 인터페이스 위치, 전원 요구, 클록 전략, 패키지 능력을 맞춥니다.","chapterIndex":3,"sentenceIndex":0},{"start":98.4905,"end":105.212729,"text":"표준화는 조정 비용을 줄이지만 모든 호환성 문제를 자동으로 해결하지 않습니다.","chapterIndex":3,"sentenceIndex":1},{"start":105.392729,"end":111.917083,"text":"조립 장면은 설계된 통합이며 아무 부품이나 꽂아 쓸 수 있다는 보장이 아닙니다.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":125.419396,"text":"단면에서는 금속과 접점을, 위에서는 메시지를 봅니다.","chapterIndex":4,"sentenceIndex":0},{"start":125.599396,"end":132.891687,"text":"물리 연결은 신뢰할 수 있는 신호 전달을, 프로토콜은 데이터의 의미와 관리를 다룹니다.","chapterIndex":4,"sentenceIndex":1},{"start":133.071687,"end":140.465354,"text":"연결 모양이 같아도 의미가 같지는 않으므로 양쪽이 실제 지원하는 기능을 확인해야 합니다.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":156.697167,"text":"기능 구역 사이의 데이터를 따라가면 경계마다 인터페이스 동작이 필요합니다.","chapterIndex":5,"sentenceIndex":0},{"start":156.877167,"end":161.445437,"text":"지나친 분할은 통신과 동기화 부담을 늘릴 수 있습니다.","chapterIndex":5,"sentenceIndex":1},{"start":161.625438,"end":168.841458,"text":"블록별 연산 성능만 더하지 말고 데이터량, 지연, 에너지 예산을 정해야 합니다.","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":183.686521,"text":"기능 지도를 개념적 열 지도로 바꿉니다.","chapterIndex":6,"sentenceIndex":0},{"start":183.866521,"end":187.461729,"text":"부하가 큰 다이와 이웃 부품의 거리를 봅니다.","chapterIndex":6,"sentenceIndex":1},{"start":187.641729,"end":194.895625,"text":"가장 뜨거운 다이, 약한 전원 경로, 혼잡한 링크가 성능을 제한할 수 있습니다.","chapterIndex":6,"sentenceIndex":2},{"start":195.075625,"end":200.565396,"text":"독립된 섬처럼 다루지 말고 전력 관리와 냉각을 조율해야 합니다.","chapterIndex":6,"sentenceIndex":3},{"start":210.35,"end":218.313375,"text":"다이가 개별적으로 작동하는지뿐 아니라 통합 시스템이 공통 조건을 만족하는지 시험합니다.","chapterIndex":7,"sentenceIndex":0},{"start":218.493375,"end":225.673521,"text":"링크 시작, 오류 처리, 목표 작업 부하를 확인하고 버전과 설정을 기록합니다.","chapterIndex":7,"sentenceIndex":1},{"start":225.853521,"end":232.751083,"text":"UCIe라는 이름이 제품 전체의 통합·상호운용성 검증을 대신하지는 않습니다.","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":248.395,"text":"칩렛 재사용은 제품 구성을 유연하게 하지만 공급업체, 버전, 검증의 조정도 늘립니다.","chapterIndex":8,"sentenceIndex":0},{"start":248.575,"end":255.642313,"text":"단일 칩과 비교할 때 개발 기간, 양품 단가, 장기 유지보수를 함께 봅니다.","chapterIndex":8,"sentenceIndex":1},{"start":255.822313,"end":260.798375,"text":"모든 요구에 맞는 분할은 없으므로 선택 근거를 남겨야 합니다.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":279.032188,"text":"기능 분할, 인터페이스 선택, 물리 패키징, 전원, 냉각, 시스템 검증을 내려다봅니다.","chapterIndex":9,"sentenceIndex":0},{"start":279.212188,"end":285.607521,"text":"각 다이의 역할, 패키지의 연결 방식, 프로토콜의 협력을 구분하세요.","chapterIndex":9,"sentenceIndex":1},{"start":285.787521,"end":293.192875,"text":"질서 있는 분담이 칩렛의 아름다움이며 전체 시스템의 작동 증거가 이를 완성합니다.","chapterIndex":9,"sentenceIndex":2}]}},"thermal":{"zh-TW":{"file":"assets/packaging-tour-v33/audio/thermal.zh-TW.m4a","sha256":"ed26553fec6f7cd91ee66a7d16bb125e024831db5753e207134a23220b3874ce","cues":[{"start":0.35,"end":10.684979,"text":"先從上方看完整封裝：晶粒、接點、基板與散熱結構要在指定環境中長期合作。","chapterIndex":0,"sentenceIndex":0},{"start":10.864979,"end":21.255646,"text":"今天的路線不只看資料流，而是問「熱能否出去、缺陷能否發現、壽命是否有證據」。","chapterIndex":0,"sentenceIndex":1},{"start":21.435646,"end":25.200771,"text":"這些問題從設計開始就要加入。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":36.382625,"text":"沿著各晶粒停靠，標出不同工作負載下的功率分布。","chapterIndex":1,"sentenceIndex":0},{"start":36.562625,"end":42.782729,"text":"總功率相同，熱點位置不同，溫度結果仍可能不同。","chapterIndex":1,"sentenceIndex":1},{"start":42.962729,"end":52.043875,"text":"散熱設計需要空間與時間資訊，不能只拿一個平均瓦數代表所有使用情境。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":67.015312,"text":"從晶粒向上飛，穿過熱介面材料、上蓋與散熱器。","chapterIndex":2,"sentenceIndex":0},{"start":67.195312,"end":73.803708,"text":"每一層的厚度、接觸狀態與材料特性都可能限制熱流。","chapterIndex":2,"sentenceIndex":1},{"start":73.983708,"end":81.705167,"text":"不是只換一個更大的散熱器就一定有效；先找真正瓶頸在哪一段。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":97.7325,"text":"把上蓋與介面分離，觀察接觸是否均勻、材料是否連續。","chapterIndex":3,"sentenceIndex":0},{"start":97.9125,"end":104.668333,"text":"厚度差與空隙可能改變熱阻，機械固定也會影響接觸。","chapterIndex":3,"sentenceIndex":1},{"start":104.848333,"end":114.023167,"text":"這是理解品質的觀察框架，不提供可直接套用到產品的壓力或材料厚度設定。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":129.422125,"text":"分層示意讓你看到熱不只往單一方向走，也可能經基板與周圍結構分流。","chapterIndex":4,"sentenceIndex":0},{"start":129.602125,"end":136.15375,"text":"簡化熱阻網路可幫助初步判斷，但必須交代模型假設。","chapterIndex":4,"sentenceIndex":1},{"start":136.33375,"end":143.511125,"text":"動畫顏色沒有溫度刻度，不能用來讀出結溫或驗收產品。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":160.083979,"text":"讓示意訊號通過系統，區分元件測試、封裝後電性測試與系統級工作負載。","chapterIndex":5,"sentenceIndex":0},{"start":160.263979,"end":162.966625,"text":"不同測試抓到不同失效。","chapterIndex":5,"sentenceIndex":1},{"start":163.146625,"end":175.245,"text":"當結果不符預期，先保存條件與症狀，再把問題縮小到供電、連線、熱或邏輯等可能來源。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":188.209417,"text":"觀看加熱與冷卻時的概念變形，不同材料會反覆拉扯接點與界面。","chapterIndex":6,"sentenceIndex":0},{"start":188.389417,"end":196.511792,"text":"可靠度關心的是時間與循環下的變化，不只是剛組裝完能否通電。","chapterIndex":6,"sentenceIndex":1},{"start":196.691792,"end":204.861604,"text":"實際試驗條件應依使用環境與適用規範制定，不能由示意動畫決定。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":215.990604,"text":"在檢查站結合影像、電性、溫度與失效位置。","chapterIndex":7,"sentenceIndex":0},{"start":216.170604,"end":221.632521,"text":"單張影像能提示異常，卻不能獨自證明根因。","chapterIndex":7,"sentenceIndex":1},{"start":221.812521,"end":233.297792,"text":"把模型預測和量測比較，記錄誤差與不確定性；只有經過驗證的數據，才應出現在工程結論裡。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":253.118854,"text":"比較兩種散熱或封裝方案時，固定工作負載、環境與量測方法，再看溫度、功耗、可靠度與成本。","chapterIndex":8,"sentenceIndex":0},{"start":253.298854,"end":259.457229,"text":"若同時改了太多條件，就難以判斷哪個改動有效。","chapterIndex":8,"sentenceIndex":1},{"start":259.637229,"end":265.064271,"text":"漂亮的下降曲線，必須能回到可重做的實驗。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":279.237813,"text":"最後升高，看需求、熱路徑、裝配品質、測試與可靠度如何連成一圈。","chapterIndex":9,"sentenceIndex":0},{"start":279.417813,"end":290.708479,"text":"先進封裝的美感不只是精密層次，而是每一條資料、電力與熱的路線都有去處，每一項結論都有證據。","chapterIndex":9,"sentenceIndex":1},{"start":290.888479,"end":296.600563,"text":"現在你可以帶著這張地圖，回到任何一種封裝技術。","chapterIndex":9,"sentenceIndex":2}]},"en":{"file":"assets/packaging-tour-v33/audio/thermal.en.m4a","sha256":"c2646e296d6a6e8ac03be63a5212d6cb4f0e6998152c53c4e2e527d5cb5bd969","cues":[{"start":0.35,"end":10.225938,"text":"Survey the complete package: dies, joints, substrate and cooling must cooperate in a specified environment over time.","chapterIndex":0,"sentenceIndex":0},{"start":10.405938,"end":17.543854,"text":"Today’s route asks whether heat can escape, defects can be found and lifetime claims have evidence.","chapterIndex":0,"sentenceIndex":1},{"start":17.723854,"end":23.576521,"text":"These questions belong at the beginning of design, not only at final inspection.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":35.265375,"text":"Visit each die and consider power distribution under different workloads.","chapterIndex":1,"sentenceIndex":0},{"start":35.445375,"end":40.423563,"text":"Equal total power can produce different temperatures when hotspots move.","chapterIndex":1,"sentenceIndex":1},{"start":40.603563,"end":49.857271,"text":"Cooling design needs spatial and time-dependent information; one average power number cannot represent every operating condition.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":65.135958,"text":"Travel upward from the die through interface material, lid and cooler.","chapterIndex":2,"sentenceIndex":0},{"start":65.315958,"end":71.447479,"text":"Thickness, contact quality and material properties can each restrict heat flow.","chapterIndex":2,"sentenceIndex":1},{"start":71.627479,"end":75.085583,"text":"A larger cooler alone may not solve the problem.","chapterIndex":2,"sentenceIndex":2},{"start":75.265583,"end":80.032979,"text":"Identify the limiting part of the path before changing the hardware.","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":96.441208,"text":"Separate lid and interface to examine uniform contact and material continuity.","chapterIndex":3,"sentenceIndex":0},{"start":96.621208,"end":104.565479,"text":"Thickness variation and voids can change thermal resistance, while mechanical attachment affects contact.","chapterIndex":3,"sentenceIndex":1},{"start":104.745479,"end":113.7985,"text":"This is an inspection framework, not a transferable prescription for clamping pressure or interface thickness on a real product.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":128.394729,"text":"The separated-layer view shows heat can split through the substrate and surrounding structures, not only move upward.","chapterIndex":4,"sentenceIndex":0},{"start":128.574729,"end":134.774021,"text":"A simplified thermal-resistance network helps early reasoning if its assumptions are stated.","chapterIndex":4,"sentenceIndex":1},{"start":134.954021,"end":143.009729,"text":"The animation has no temperature scale and cannot provide junction-temperature readings or product acceptance results.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":158.516396,"text":"Follow a test signal and distinguish component tests, post-package electrical tests and system workloads.","chapterIndex":5,"sentenceIndex":0},{"start":158.696396,"end":160.92475,"text":"They expose different failures.","chapterIndex":5,"sentenceIndex":1},{"start":161.10475,"end":172.907208,"text":"When a result is unexpected, preserve conditions and symptoms before narrowing the cause to power, interconnect, temperature, logic or another subsystem.","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":187.842625,"text":"Watch conceptual expansion and contraction as different materials load joints and interfaces repeatedly.","chapterIndex":6,"sentenceIndex":0},{"start":188.022625,"end":195.846,"text":"Reliability concerns change over time and cycling, not merely successful power-on after assembly.","chapterIndex":6,"sentenceIndex":1},{"start":196.026,"end":205.968604,"text":"Real test conditions must follow the use environment and applicable qualification requirements, never the timing of this illustration.","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":216.467062,"text":"Combine images, electrical results, temperatures and failure locations.","chapterIndex":7,"sentenceIndex":0},{"start":216.647063,"end":220.770708,"text":"One image can suggest a problem without proving its cause.","chapterIndex":7,"sentenceIndex":1},{"start":220.950708,"end":225.986812,"text":"Compare model predictions with measurements and record error and uncertainty.","chapterIndex":7,"sentenceIndex":2},{"start":226.166812,"end":234.204104,"text":"Engineering conclusions should be supported by validated data rather than the apparent realism of a visualization.","chapterIndex":7,"sentenceIndex":3},{"start":240.35,"end":252.120396,"text":"Compare package or cooling options under the same workload, environment and measurement method, then evaluate temperature, power, reliability and cost.","chapterIndex":8,"sentenceIndex":0},{"start":252.300396,"end":256.201083,"text":"Changing many conditions at once obscures causality.","chapterIndex":8,"sentenceIndex":1},{"start":256.381083,"end":262.303042,"text":"An attractive improvement curve must be traceable to an experiment that can be repeated.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":279.105167,"text":"Rise to see requirements, heat paths, assembly quality, testing and reliability form a feedback loop.","chapterIndex":9,"sentenceIndex":0},{"start":279.285167,"end":286.889354,"text":"Advanced packaging is beautiful when data, power and heat have deliberate routes and conclusions have evidence.","chapterIndex":9,"sentenceIndex":1},{"start":287.069354,"end":293.835854,"text":"Carry this map back to any packaging technology and ask how the complete system is verified.","chapterIndex":9,"sentenceIndex":2}]},"zh-CN":{"file":"assets/packaging-tour-v33/audio/thermal.zh-CN.m4a","sha256":"d8a336af065bd3a4cb8247633aa188a6ca671f09427e3a45c82ae5c095def870","cues":[{"start":0.35,"end":10.288021,"text":"先从上方看完整封装：晶粒、接点、基板与散热结构要在指定环境中长期合作。","chapterIndex":0,"sentenceIndex":0},{"start":10.468021,"end":20.562687,"text":"今天的路线不只看数据流，而是问热能否出去、缺陷能否发现、寿命是否有证据。","chapterIndex":0,"sentenceIndex":1},{"start":20.742687,"end":24.279479,"text":"这些问题从设计开始就要加入。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":36.915,"text":"沿着各晶粒停靠，标出不同工作负载下的功率分布。","chapterIndex":1,"sentenceIndex":0},{"start":37.095,"end":43.767479,"text":"总功率相同，热点位置不同，温度结果仍可能不同。","chapterIndex":1,"sentenceIndex":1},{"start":43.947479,"end":53.442813,"text":"散热设计需要空间与时间信息，不能只拿一个平均瓦数代表所有使用情境。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":67.246604,"text":"从晶粒向上飞，穿过热界面材料、上盖与散热器。","chapterIndex":2,"sentenceIndex":0},{"start":67.426604,"end":74.323042,"text":"每一层的厚度、接触状态与材料特性都可能限制热流。","chapterIndex":2,"sentenceIndex":1},{"start":74.503042,"end":82.446417,"text":"不是只换一个更大的散热器就一定有效；先找真正瓶颈在哪一段。","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":97.983333,"text":"把上盖与界面分离，观察接触是否均匀、材料是否连续。","chapterIndex":3,"sentenceIndex":0},{"start":98.163333,"end":105.220812,"text":"厚度差与空隙可能改变热阻，机械固定也会影响接触。","chapterIndex":3,"sentenceIndex":1},{"start":105.400813,"end":114.824729,"text":"这是理解质量的观察框架，不提供可直接套用到产品的压力或材料厚度设置。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":129.565167,"text":"分层示意让你看到热不只往单一方向走，也可能经基板与周围结构分流。","chapterIndex":4,"sentenceIndex":0},{"start":129.745167,"end":136.893708,"text":"简化热阻网络可帮助初步判断，但必须交代模型假设。","chapterIndex":4,"sentenceIndex":1},{"start":137.073708,"end":144.200063,"text":"动画颜色没有温度刻度，不能用来读出结温或验收产品。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":159.62375,"text":"让示意信号通过系统，区分元件测试、封装后电性测试与系统级工作负载。","chapterIndex":5,"sentenceIndex":0},{"start":159.80375,"end":162.557417,"text":"不同测试抓到不同失效。","chapterIndex":5,"sentenceIndex":1},{"start":162.737417,"end":174.371896,"text":"当结果不符预期，先保存条件与症状，再把问题缩小到供电、连线、热或逻辑等可能来源。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":188.298083,"text":"观看加热与冷却时的概念变形，不同材料会反复拉扯接点与界面。","chapterIndex":6,"sentenceIndex":0},{"start":188.478083,"end":196.185354,"text":"可靠性关心的是时间与循环下的变化，不只是刚组装完能否通电。","chapterIndex":6,"sentenceIndex":1},{"start":196.365354,"end":204.294354,"text":"实际试验条件应依使用环境与适用规范制定，不能由示意动画决定。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":216.502208,"text":"在检查站结合影像、电性、温度与失效位置。","chapterIndex":7,"sentenceIndex":0},{"start":216.682208,"end":222.483125,"text":"单张影像能提示异常，却不能独自证明根因。","chapterIndex":7,"sentenceIndex":1},{"start":222.663125,"end":234.990521,"text":"把模型预测和测量比较，记录误差与不确定性；只有经过验证的数据，才应出现在工程结论里。","chapterIndex":7,"sentenceIndex":2},{"start":240.35,"end":252.848604,"text":"比较两种散热或封装方案时，固定工作负载、环境与测量方法，再看温度、功耗、可靠性与成本。","chapterIndex":8,"sentenceIndex":0},{"start":253.028604,"end":258.866479,"text":"若同时改了太多条件，就难以判断哪个改动有效。","chapterIndex":8,"sentenceIndex":1},{"start":259.046479,"end":264.355417,"text":"漂亮的下降曲线，必须能回到可重做的实验。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":278.725292,"text":"最后升高，看需求、热路径、装配质量、测试与可靠性如何连成一圈。","chapterIndex":9,"sentenceIndex":0},{"start":278.905292,"end":289.771833,"text":"先进封装的美感不只是精密层次，而是每一条数据、电力与热的路线都有去处，每一项结论都有证据。","chapterIndex":9,"sentenceIndex":1},{"start":289.951833,"end":295.549083,"text":"现在你可以带着这张地图，回到任何一种封装技术。","chapterIndex":9,"sentenceIndex":2}]},"ja":{"file":"assets/packaging-tour-v33/audio/thermal.ja.m4a","sha256":"66b02b56ac4d7448fd4f4380f167925c9b4ae1c6557676578a00102a942865e1","cues":[{"start":0.35,"end":9.095083,"text":"ダイ、接点、基板、冷却が所定環境で長く協調する必要があります。","chapterIndex":0,"sentenceIndex":0},{"start":9.275083,"end":16.469792,"text":"今日は熱の出口、欠陥の発見、寿命の根拠をたどります。","chapterIndex":0,"sentenceIndex":1},{"start":16.649792,"end":25.05275,"text":"これらは最終検査だけの問題ではなく、設計の最初から考える問いです。","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":35.201354,"text":"各ダイで負荷ごとの電力分布を考えます。","chapterIndex":1,"sentenceIndex":0},{"start":35.381354,"end":41.427625,"text":"総電力が同じでも熱点の位置で温度は変わります。","chapterIndex":1,"sentenceIndex":1},{"start":41.607625,"end":53.639208,"text":"冷却設計には場所と時間の情報が必要で、一つの平均電力だけでは全使用条件を表せません。","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":65.764604,"text":"ダイから界面材料、ふた、冷却器へ上がります。","chapterIndex":2,"sentenceIndex":0},{"start":65.944604,"end":72.624021,"text":"厚さ、接触状態、材料特性が熱流を制限します。","chapterIndex":2,"sentenceIndex":1},{"start":72.804021,"end":78.672521,"text":"冷却器だけを大型化しても解決しない場合があります。","chapterIndex":2,"sentenceIndex":2},{"start":78.852521,"end":84.907,"text":"部品変更の前に、経路のどこが律速かを探します。","chapterIndex":2,"sentenceIndex":3},{"start":90.35,"end":97.481479,"text":"ふたと界面を分け、均一な接触と材料の連続性を見ます。","chapterIndex":3,"sentenceIndex":0},{"start":97.661479,"end":104.897458,"text":"厚さの差や空隙は熱抵抗を変え、固定方法も影響します。","chapterIndex":3,"sentenceIndex":1},{"start":105.077458,"end":115.2235,"text":"これは品質を見る枠組みで、実製品へそのまま適用できる圧力や厚さの設定ではありません。","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":126.538854,"text":"熱は上だけでなく、基板や周囲にも分かれて流れます。","chapterIndex":4,"sentenceIndex":0},{"start":126.718854,"end":133.427521,"text":"仮定を明示した簡易熱抵抗網は初期検討に役立ちます。","chapterIndex":4,"sentenceIndex":1},{"start":133.607521,"end":143.387708,"text":"映像の色には温度目盛がなく、接合温度の読み取りや製品合否判定には使えません。","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":159.233271,"text":"試験信号を追い、部品試験、パッケージ化後の電気試験、システム負荷を区別します。","chapterIndex":5,"sentenceIndex":0},{"start":159.413271,"end":162.70875,"text":"検出する故障は異なります。","chapterIndex":5,"sentenceIndex":1},{"start":162.88875,"end":173.522188,"text":"予想外の結果では条件と症状を保存し、電源、配線、熱、論理などへ原因を絞ります。","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":188.478396,"text":"加熱と冷却で異なる材料が接点と界面に繰り返し力を与えます。","chapterIndex":6,"sentenceIndex":0},{"start":188.658396,"end":197.868708,"text":"信頼性は組立直後の通電だけでなく、時間と繰返しによる変化を扱います。","chapterIndex":6,"sentenceIndex":1},{"start":198.048708,"end":206.157917,"text":"実試験条件は使用環境と適用要件で定め、映像の周期から決めません。","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":216.008688,"text":"画像、電気結果、温度、故障位置を照合します。","chapterIndex":7,"sentenceIndex":0},{"start":216.188688,"end":222.437729,"text":"一枚の画像は異常を示唆しても根因を証明できません。","chapterIndex":7,"sentenceIndex":1},{"start":222.617729,"end":228.036333,"text":"予測と測定を比べ、誤差と不確かさを記録します。","chapterIndex":7,"sentenceIndex":2},{"start":228.216333,"end":235.01425,"text":"見た目のリアルさではなく、検証済みデータで結論を支えます。","chapterIndex":7,"sentenceIndex":3},{"start":240.35,"end":249.397812,"text":"同じ負荷、環境、測定方法で温度、電力、信頼性、費用を比べます。","chapterIndex":8,"sentenceIndex":0},{"start":249.577812,"end":255.718312,"text":"多くの条件を同時に変えると、何が効いたか分かりません。","chapterIndex":8,"sentenceIndex":1},{"start":255.898313,"end":263.528354,"text":"美しい改善曲線も、再現できる実験へ戻れる必要があります。","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":278.8775,"text":"要求、熱経路、組立品質、試験、信頼性が循環する全体を見ます。","chapterIndex":9,"sentenceIndex":0},{"start":279.0575,"end":287.133979,"text":"データ、電力、熱に意図した経路があり、結論に根拠があることが美しさです。","chapterIndex":9,"sentenceIndex":1},{"start":287.313979,"end":294.679062,"text":"この地図を持って、どのパッケージ技術でもシステム全体の検証を問いましょう。","chapterIndex":9,"sentenceIndex":2}]},"ko":{"file":"assets/packaging-tour-v33/audio/thermal.ko.m4a","sha256":"8bbbc993b450d4f3ace14ba438a0614accbc98b6ceaf1af01bd94f4e1d052d91","cues":[{"start":0.35,"end":8.218167,"text":"다이, 접점, 기판, 냉각 구조는 정해진 환경에서 오랫동안 함께 작동해야 합니다.","chapterIndex":0,"sentenceIndex":0},{"start":8.398167,"end":16.616187,"text":"오늘은 열이 빠져나가는지, 결함을 찾을 수 있는지, 수명 주장에 증거가 있는지 살펴봅니다.","chapterIndex":0,"sentenceIndex":1},{"start":16.796187,"end":22.157021,"text":"이 질문은 최종 검사뿐 아니라 설계 초기부터 포함해야 합니다.","chapterIndex":0,"sentenceIndex":2},{"start":30.35,"end":35.222896,"text":"각 다이에서 작업 부하에 따른 전력 분포를 살펴봅니다.","chapterIndex":1,"sentenceIndex":0},{"start":35.402896,"end":41.207979,"text":"총전력이 같아도 열점 위치가 바뀌면 온도가 달라질 수 있습니다.","chapterIndex":1,"sentenceIndex":1},{"start":41.387979,"end":50.139375,"text":"냉각 설계에는 공간과 시간 정보가 필요하며 평균 전력 하나로 모든 사용 조건을 대표할 수 없습니다.","chapterIndex":1,"sentenceIndex":2},{"start":60.35,"end":65.101521,"text":"다이에서 계면 재료, 덮개, 냉각기로 올라갑니다.","chapterIndex":2,"sentenceIndex":0},{"start":65.281521,"end":71.606063,"text":"두께, 접촉 품질, 재료 특성은 각각 열 이동을 제한할 수 있습니다.","chapterIndex":2,"sentenceIndex":1},{"start":71.786062,"end":79.549021,"text":"냉각기를 크게 바꾸는 것만으로 해결되지 않을 수 있으므로 먼저 실제 병목 구간을 찾아야 합니다.","chapterIndex":2,"sentenceIndex":2},{"start":90.35,"end":95.931875,"text":"덮개와 계면을 분리해 접촉 균일성과 재료 연속성을 확인합니다.","chapterIndex":3,"sentenceIndex":0},{"start":96.111875,"end":102.555604,"text":"두께 편차와 빈틈은 열저항을 바꾸고 고정 방식도 접촉에 영향을 줍니다.","chapterIndex":3,"sentenceIndex":1},{"start":102.735604,"end":110.115562,"text":"이는 품질 관찰 틀이며 실제 제품에 그대로 적용할 압력이나 두께 설정값은 아닙니다.","chapterIndex":3,"sentenceIndex":2},{"start":120.35,"end":125.387375,"text":"열은 위로만 흐르지 않고 기판과 주변 구조로 나뉘기도 합니다.","chapterIndex":4,"sentenceIndex":0},{"start":125.567375,"end":130.846792,"text":"가정을 명시한 단순 열저항망은 초기 판단에 도움이 됩니다.","chapterIndex":4,"sentenceIndex":1},{"start":131.026792,"end":138.893792,"text":"애니메이션 색에는 온도 눈금이 없으므로 접합 온도를 읽거나 제품 합격을 판정할 수 없습니다.","chapterIndex":4,"sentenceIndex":2},{"start":150.35,"end":158.301125,"text":"시험 신호를 따라 부품 시험, 패키징 후 전기 시험, 시스템 작업 부하를 구분합니다.","chapterIndex":5,"sentenceIndex":0},{"start":158.481125,"end":161.322125,"text":"각 시험은 다른 고장을 드러냅니다.","chapterIndex":5,"sentenceIndex":1},{"start":161.502125,"end":170.059146,"text":"예상과 다르면 조건과 증상을 보존한 뒤 전원, 연결, 온도, 논리 등으로 원인을 좁힙니다.","chapterIndex":5,"sentenceIndex":2},{"start":180.35,"end":186.351687,"text":"가열과 냉각에서 서로 다른 재료가 접점과 계면에 반복 하중을 줍니다.","chapterIndex":6,"sentenceIndex":0},{"start":186.531688,"end":193.729833,"text":"신뢰성은 조립 직후 전원이 켜지는 것뿐 아니라 시간과 반복에 따른 변화를 다룹니다.","chapterIndex":6,"sentenceIndex":1},{"start":193.909833,"end":201.881458,"text":"실제 시험 조건은 사용 환경과 적용 요구사항으로 정해야 하며 영상 주기를 따라서는 안 됩니다.","chapterIndex":6,"sentenceIndex":2},{"start":210.35,"end":215.8155,"text":"영상, 전기 결과, 온도, 고장 위치를 함께 봅니다.","chapterIndex":7,"sentenceIndex":0},{"start":215.9955,"end":221.241083,"text":"한 장의 영상은 이상을 시사해도 원인을 증명하지는 못합니다.","chapterIndex":7,"sentenceIndex":1},{"start":221.421083,"end":226.839833,"text":"모델 예측과 측정을 비교하고 오차와 불확실성을 기록합니다.","chapterIndex":7,"sentenceIndex":2},{"start":227.019833,"end":233.521479,"text":"사실적인 화면이 아니라 검증된 데이터로 공학적 결론을 뒷받침해야 합니다.","chapterIndex":7,"sentenceIndex":3},{"start":240.35,"end":248.682938,"text":"같은 작업 부하, 환경, 측정 방법으로 온도, 전력, 신뢰성, 비용을 비교합니다.","chapterIndex":8,"sentenceIndex":0},{"start":248.862937,"end":255.079313,"text":"여러 조건을 동시에 바꾸면 어떤 변경이 효과가 있었는지 알기 어렵습니다.","chapterIndex":8,"sentenceIndex":1},{"start":255.259312,"end":261.285042,"text":"보기 좋은 개선 곡선도 반복 가능한 실험으로 추적할 수 있어야 합니다.","chapterIndex":8,"sentenceIndex":2},{"start":270.35,"end":278.687979,"text":"요구사항, 열 경로, 조립 품질, 시험, 신뢰성이 피드백 고리를 이루는 전체를 봅니다.","chapterIndex":9,"sentenceIndex":0},{"start":278.867979,"end":287.352333,"text":"데이터·전력·열에 의도된 경로가 있고 결론에 증거가 있을 때 첨단 패키징은 아름답습니다.","chapterIndex":9,"sentenceIndex":1},{"start":287.532333,"end":294.220062,"text":"이 지도를 가지고 어떤 패키징 기술에서도 전체 시스템의 검증을 물어보세요.","chapterIndex":9,"sentenceIndex":2}]}}}};
